import{g as o,ad as a,r as t,A as d}from"./chunks/framework.BT7BGxmb.js";const u=JSON.parse('{"title":"Frappe UI v1 Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"docs/changelog.md","filePath":"docs/changelog.md","lastUpdated":1786387155000}'),s={name:"docs/changelog.md"};function r(c,e,n,i,l,p){return a(),t("div",null,[...e[0]||(e[0]=[d(`<h1 id="frappe-ui-v1-changelog" tabindex="-1">Frappe UI v1 Changelog <a class="header-anchor" href="#frappe-ui-v1-changelog" aria-label="Permalink to “Frappe UI v1 Changelog”">​</a></h1><p>User-facing v1 changes. <strong>Unreleased</strong> entries describe changes since <strong>v0.1.278</strong>. Log only breaking changes, deprecations, observable behavior changes, and migration guidance — not internal refactors or test additions.</p><p>All deprecations preserve backwards compatibility through v1.x and emit a one-time dev-mode warning (unless noted). Removal is post-v1.</p><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to “Unreleased”">​</a></h2><h3 id="data-fetching-v2-—-stale-responses-no-longer-write-the-shared-stores-fix" tabindex="-1">Data fetching (v2) — stale responses no longer write the shared stores (fix) <a class="header-anchor" href="#data-fetching-v2-—-stale-responses-no-longer-write-the-shared-stores-fix" aria-label="Permalink to “Data fetching (v2) — stale responses no longer write the shared stores (fix)”">​</a></h3><p>Two concurrent writes to one document could leave <code>docStore</code>, <code>listStore</code> (and every view bound to them) on the response that settled last instead of the newest one, while <code>data</code> already held the fresh response (#1017).</p><p>The gate lives in the stores. Every request takes a dispatch version; the response&#39;s store writes carry it, and the stores reject a write for a document that a later-dispatched request has already written. One freshness domain covers every writer — the <code>docs</code> side channel, the <code>useDoctype</code> / <code>useList</code> / <code>useDoc</code> hooks, and any mix of instances or paths writing the same document. A version is recorded only when a mutating write lands: a newer request that failed wrote nothing on the server, so it does not make the older success stale, and a read (GET) is admitted on its version but records nothing — the server may answer a later reload before an earlier save commits, and the save must still land. A delete records a fresh version when it settles — a delete is terminal — so no in-flight write or reload, whatever its dispatch order, can re-create a deleted document. One accepted limitation: the gate orders by dispatch time, so a read dispatched after a save, handled by the server before the save committed and answered after it, is admitted and republishes the pre-save value — resolving that needs server-side sequencing, which this design trades away.</p><p><code>useAction</code> still skips the <code>onSuccess</code>/<code>onError</code> hooks of a submit that a newer same-key submit of the same instance already outran — the store gate protects the stores, this skip only avoids re-running hook side effects with a stale response. <code>useDoc</code>&#39;s write members and <code>useNewDoc</code> skip their hooks the same way, but their store writes stay outside that skip: only the store gate decides them. It compares per document and knows whether the newer request landed, so an overtaken insert of a different document still lands, and an older success is kept when the newer submit failed.</p><p>No API change. Behavior changes if you relied on it:</p><ul><li>A stale <code>setValue</code>/<code>delete</code> on the same document no longer triggers <code>useList</code>&#39;s auto-refetch; the newest submit&#39;s refetch already ran.</li><li>Submits with different keys, and keyless submits (inserts), are independent — all of their hooks still fire, as before.</li></ul><h3 id="charts-—-a-new-family-at-frappe-ui-charts" tabindex="-1">Charts — a new family at <code>frappe-ui/charts</code> <a class="header-anchor" href="#charts-—-a-new-family-at-frappe-ui-charts" aria-label="Permalink to “Charts — a new family at frappe-ui/charts”">​</a></h3><p>A second chart family ships alongside the one at the package root. It is additive: the root chart exports keep working and nothing here removes them. Import the components from <code>frappe-ui/charts</code>, which carries the <code>--chart-*</code> color tokens with it. <code>spec/charts.md</code> states the conventions, and <code>spec/adr/0015-what-enters-charts.md</code> records what the family admits.</p><p>Landed so far:</p><ul><li>The chrome is exported — <code>ChartCard</code>, <code>ChartContainer</code>, <code>ChartLegend</code> and <code>ChartTooltip</code> — so a plot an app draws itself wears the family&#39;s look. <code>ChartCard</code> owns the card surface, and <code>card: false</code> turns it off.</li><li>Combo series through <code>seriesConfig[key].type</code>, which also collapsed the three axis option builders into one. Per-series area fill falls out of it.</li><li>Reference lines on the axis charts and on <code>ScatterChart</code>. A line beyond the data range is clipped rather than stretching the value axis.</li><li><code>stacked: &#39;normalized&#39;</code> for shares, and <code>maxSeries</code> to cap a long grouping column. <code>maxSeries</code> has no default.</li><li><code>ScatterChart</code> and <code>SankeyChart</code>.</li><li>Category labels fit themselves — the library measures, tilts and truncates instead of taking an angle prop.</li><li><code>xAxis.type: &#39;value&#39;</code> reads the x column as a quantity: a point sits at its own number instead of in its row&#39;s slot, and the rows draw in numeric order. Ask for it — a column of numbers still reads as categories by default.</li><li>The three states are slots — <code>#loading</code>, <code>#error</code> and <code>#empty</code> — on <code>ChartContainer</code> and on every chart component, so an app puts a retry button beside a failed query without drawing chrome of its own. <code>#loading</code> replaces the whole placeholder rather than a caption under a spinner.</li><li>A loading chart draws a skeleton the size of its plot, where it used to draw a spinner and the words &quot;Loading chart…&quot;. A dashboard fills in a card at a time, and a placeholder that holds the grid&#39;s shape reads better than eight spinners turning out of step. <code>#loading</code> takes it back.</li><li><code>seriesConfig[key].axis</code> puts a series on the second value axis. It replaces the <code>y2</code> prop, <strong>which is removed</strong>: <code>y</code> names every series once, in the order they are drawn and colored, so a series no longer changes color when it changes axis. Long data reaches the second axis for the first time, keyed by a value of the <code>series</code> column, and <code>y2Axis</code> is unchanged. To migrate, move each <code>y2</code> column into <code>y</code> at the position it should draw at and add <code>axis: &#39;y2&#39;</code> to that column&#39;s <code>seriesConfig</code> entry. TypeScript reports the removed prop, but a plain template passes it through as an attribute and draws the column not at all — grep for <code>y2</code> on the v2 charts after upgrading.</li><li><code>ScatterChart</code> takes <code>showDataLabels</code>, which prints each point&#39;s <code>label</code> beside it. Names that collide with a neighbour are dropped.</li><li><code>NumberCard</code> takes <code>color</code>, the ink the reading is printed in, for a card standing for a series drawn in that color elsewhere. The card, the title and the delta tone are unchanged by it.</li></ul><p>Changed since <code>1.0.0-beta.41</code>, the first beta that shipped the family:</p><ul><li><strong>Breaking, silent:</strong> the six mark emits are renamed to <code>select</code> — <code>datapointClick</code> on <code>AreaChart</code>, <code>BarChart</code> and <code>LineChart</code>, <code>sliceClick</code> on <code>DonutChart</code>, <code>stageClick</code> on <code>FunnelChart</code>, <code>cellClick</code> on <code>HeatmapChart</code>, <code>linkClick</code> on <code>SankeyChart</code> and <code>pointClick</code> on <code>ScatterChart</code>. P1 names an emit after the behavior, and the six now fire from the keyboard as well, so &quot;click&quot; was false. A listener on an old name stops firing with no error — see the <a href="https://frappeui.com/docs/migration#charts" target="_blank" rel="noreferrer">migration guide</a>. The payload types are unchanged.</li><li><strong>Breaking, loud:</strong> <code>ChartTheme</code> is now <code>ChartTokens</code> and <code>useChartTheme</code> is now <code>useChartTokens</code>, which returns <code>{ tokens }</code> rather than <code>{ theme }</code>. <code>theme</code> means a color tone everywhere else in the library (P4), and these are the resolved <code>--chart-*</code> values.</li><li><strong>Breaking, loud:</strong> <code>formatValue</code>, <code>formatDate</code>, <code>formatLabel</code>, <code>formatPercent</code>, <code>formatAxisValue</code>, <code>currentColorScheme</code> and <code>resolveChartTheme</code> are no longer exported. They had no documented use, and each format helper hardcodes <code>en-US</code>. Read the plot-area colors with <code>useChartTokens</code>, which re-resolves on a theme flip; <code>currentColorScheme</code> was the root <code>resolvedColorScheme</code> under another name.</li></ul><h3 id="calendar-family-—-moved-to-frappe-ui-experimental-breaking" tabindex="-1">Calendar family — moved to <code>frappe-ui/experimental</code> (breaking) <a class="header-anchor" href="#calendar-family-—-moved-to-frappe-ui-experimental-breaking" aria-label="Permalink to “Calendar family — moved to frappe-ui/experimental (breaking)”">​</a></h3><p>Calendar is not taken to bar at root for <code>1.0.0</code> (#1020, redirect of #989). It parks on <code>frappe-ui/experimental</code> (P14 — no stability promise) with its public API unchanged, until a redesigned calendar family replaces it.</p><ul><li><strong>Breaking, loud:</strong> <code>import { Calendar, ... } from &#39;frappe-ui&#39;</code> fails to resolve. Import from <code>frappe-ui/experimental</code> instead: <code>Calendar</code>, <code>CalendarColorMap</code>, <code>CalendarActiveEvent</code>, and the types <code>CalendarActions</code>, <code>CalendarCellClickData</code>, <code>CalendarConfig</code>, <code>CalendarEvent</code>, <code>CalendarMode</code>, <code>CalendarPublicProps</code>, <code>CalendarTimeFormat</code>, <code>GroupedCalendarEvents</code>. Migration is the import-path change only. Apps that spread <code>content</code> from <code>frappe-ui/tailwind</code> keep Calendar styles automatically.</li><li><strong>Fix:</strong> the default header&#39;s month-title button renders again (it broke when DatePicker&#39;s <code>#target</code> slot became <code>#trigger</code>), and the all-day collapse buttons show their chevron icons again.</li></ul><h3 id="radius-aliases-and-text-black-styles-removed-breaking-silent" tabindex="-1">Radius aliases and <code>text-*-black</code> styles removed (breaking, silent) <a class="header-anchor" href="#radius-aliases-and-text-black-styles-removed-breaking-silent" aria-label="Permalink to “Radius aliases and text-*-black styles removed (breaking, silent)”">​</a></h3><p>Per ADR-0006 and ADR-0008 (#998, decided in #993):</p><ul><li>The named radius aliases (<code>rounded</code>, <code>rounded-sm</code>, <code>rounded-md</code>, <code>rounded-lg</code>, <code>rounded-xl</code>, <code>rounded-2xl</code>, and their directional forms) are removed. Numbered tokens are the only radius vocabulary (<code>rounded</code> → <code>rounded-4</code>, sm→1, md→5, lg→6, xl→7, 2xl→8; identical px). <code>rounded-none</code> and <code>rounded-full</code> stay. <strong>Silent break:</strong> the preset replaces Tailwind&#39;s scale, so an unmigrated alias emits no CSS — square corners, no build error. The <code>tokens-v2</code> codemod now performs these renames (idempotent, runs in every mode); it rewrites bare <code>rounded</code> only inside quoted strings and <code>@apply</code> rules, so grep for leftovers.</li><li>The <code>text-&lt;size&gt;-black</code> / <code>text-p-&lt;size&gt;-black</code> style classes are removed (zero usage; the Figma black weights were corrupt export data). Also a silent break. The codemod flags <code>font-extrabold</code> / <code>font-black</code> next to a text size instead of merging onto the removed class.</li></ul><h3 id="listfilter-—-removed-breaking" tabindex="-1">ListFilter — removed (breaking) <a class="header-anchor" href="#listfilter-—-removed-breaking" aria-label="Permalink to “ListFilter — removed (breaking)”">​</a></h3><ul><li><strong>Breaking, loud:</strong> <code>ListFilter</code> is no longer exported — the import fails. Its internals (<code>SearchComplete</code>, <code>FilterIcon</code>) are gone with it (#992, #999). No consumer app used it. Build filter UI in app code with <code>Select</code> and <code>Combobox</code>.</li></ul><h3 id="data-fetching-v2-—-usedoc-writes-and-usenewdoc-get-one-request-per-submit-fix" tabindex="-1">Data fetching (v2) — <code>useDoc</code> writes and <code>useNewDoc</code> get one request per submit (fix) <a class="header-anchor" href="#data-fetching-v2-—-usedoc-writes-and-usenewdoc-get-one-request-per-submit-fix" aria-label="Permalink to “Data fetching (v2) — useDoc writes and useNewDoc get one request per submit (fix)”">​</a></h3><p><code>useDoc</code>&#39;s <code>setValue</code>, <code>delete</code> and every <code>methods:</code> entry, and <code>useNewDoc</code>, still held a single shared request after the <code>useDoctype</code>/<code>useList</code> fix. Two submits at once aborted one another, and every submit resolved from the same <code>data</code>, so a caller could receive another caller&#39;s answer or <code>null</code>. Each submit now sends its own request and resolves with its own response (#991).</p><ul><li>No API change. These members keep the full <code>useCall</code> surface — same members, same types. <code>submit()</code> still resolves <code>null</code> on a failed request.</li><li><code>data</code> and <code>error</code> belong to the submit that started last, same as <code>useDoctype</code> and <code>useList</code>: a stale submit answers its own caller and writes nothing shared. <code>loading</code> stays <code>true</code> until every submit settles.</li><li>Behavior change if you relied on it: a second submit no longer cancels the first — both requests reach the server.</li></ul><h3 id="sprite-icon-trio-—-moved-to-frappe-ui-experimental-breaking" tabindex="-1">Sprite icon trio — moved to <code>frappe-ui/experimental</code> (breaking) <a class="header-anchor" href="#sprite-icon-trio-—-moved-to-frappe-ui-experimental-breaking" aria-label="Permalink to “Sprite icon trio — moved to frappe-ui/experimental (breaking)”">​</a></h3><p>The sprite-based <code>Icon</code>, <code>IconPicker</code>, and <code>spritePlugin</code> leave <code>frappe-ui/icons</code> (#904). Apps still use them, so they park on <code>frappe-ui/experimental</code> (P14 — no stability promise) instead of being deleted. <code>lucide-*</code> classes are the canonical way to render icons. The named SFC icons (<code>CircleCheckIcon</code>, <code>HelpIcon</code>, ...) stay on <code>frappe-ui/icons</code>.</p><ul><li><strong>Breaking, loud:</strong> <code>import { Icon, IconPicker, spritePlugin } from &#39;frappe-ui/icons&#39;</code> fails to resolve. Import from <code>frappe-ui/experimental</code> instead. Migration is the import-path change only. Apps that spread <code>content</code> from <code>frappe-ui/tailwind</code> keep <code>IconPicker</code> styles automatically — no Tailwind change needed.</li><li><code>frappe-ui/experimental</code> exports <code>Icon</code> (sprite); root <code>frappe-ui</code> exports a different <code>Icon</code>. Alias one if you import both: <code>import { Icon as SpriteIcon } from &#39;frappe-ui/experimental&#39;</code>.</li></ul><h3 id="createlistresource-—-haspreviouspage-stale-after-reload-fix" tabindex="-1"><code>createListResource</code> — <code>hasPreviousPage</code> stale after <code>reload()</code> (fix) <a class="header-anchor" href="#createlistresource-—-haspreviouspage-stale-after-reload-fix" aria-label="Permalink to “createListResource — hasPreviousPage stale after reload() (fix)”">​</a></h3><p><code>reload()</code> temporarily resets <code>start</code> to <code>0</code> to re-fetch the accumulated pages as one request, then restores it. <code>hasPreviousPage</code> was computed while <code>start</code> was still <code>0</code> and never recomputed after the restore, so it stayed <code>false</code> even when <code>start</code> was back above <code>0</code>. <code>reload()</code> now recomputes <code>hasPreviousPage</code> after restoring <code>start</code>.</p><h3 id="commandpalette-—-show-renamed-to-open-breaking-silent" tabindex="-1">CommandPalette — <code>show</code> renamed to <code>open</code> (breaking, silent) <a class="header-anchor" href="#commandpalette-—-show-renamed-to-open-breaking-silent" aria-label="Permalink to “CommandPalette — show renamed to open (breaking, silent)”">​</a></h3><p><code>show</code> → <code>open</code>, matching the rest of the library&#39;s overlay vocabulary (<code>CONTEXT.md</code>). <strong>Silent break:</strong> Vue accepts the unknown <code>show</code> prop with no error, so the palette just never opens — grep for <code>CommandPalette</code> and <code>v-model:show</code> after upgrading. <code>Mod+K</code> now opens the palette on its own (registered internally via <code>useShortcut</code>); delete any app-level keydown listener that toggled it. <code>CommandPalette</code> and <code>CommandPaletteItem</code> also gained <code>types.ts</code>, docs, stories, and a Cypress test; item icons now accept <code>string | Component</code> (lucide class strings, emoji, or a component) instead of components only.</p><h3 id="keyboardshortcut-—-deprecated-shortcut-and-unused-modifier-props-removed-breaking" tabindex="-1">KeyboardShortcut — deprecated <code>shortcut</code> and unused modifier props removed (breaking) <a class="header-anchor" href="#keyboardshortcut-—-deprecated-shortcut-and-unused-modifier-props-removed-breaking" aria-label="Permalink to “KeyboardShortcut — deprecated shortcut and unused modifier props removed (breaking)”">​</a></h3><p>Per ADR-0008, the deprecated <code>shortcut</code> prop (superseded by <code>combo</code>) is removed rather than shipped frozen — it had zero call sites. The <code>meta</code> / <code>ctrl</code> / <code>shift</code> / <code>alt</code> boolean props are also removed (Rule 9: zero real usage, superseded by <code>combo</code>). Both are <strong>loud</strong> breaks (removed props on a typed component). Also moved from a bare <code>KeyboardShortcut.vue</code> into its own directory with a <code>types.ts</code>, a docs page, and a Cypress test.</p><h3 id="useshortcut-—-matchesshortcut-no-longer-public-breaking" tabindex="-1">useShortcut — <code>matchesShortcut</code> no longer public (breaking) <a class="header-anchor" href="#useshortcut-—-matchesshortcut-no-longer-public-breaking" aria-label="Permalink to “useShortcut — matchesShortcut no longer public (breaking)”">​</a></h3><p><code>matchesShortcut</code> is removed from the <code>frappe-ui</code> package export. Its own doc comment already said &quot;exported for unit tests only&quot; — it was never meant to be public API (Rule 9). Loud break (import error) for anyone who imported it directly; no signal of any real consumer doing so.</p><h3 id="keyboardshortcutsmodal-useshortcut-—-brought-to-bar" tabindex="-1">KeyboardShortcutsModal / useShortcut — brought to bar <a class="header-anchor" href="#keyboardshortcutsmodal-useshortcut-—-brought-to-bar" aria-label="Permalink to “KeyboardShortcutsModal / useShortcut — brought to bar”">​</a></h3><p><code>KeyboardShortcutsModal</code> gained a <code>types.ts</code> and a Cypress test (previously only unit-tested). <code>useShortcut</code> gained a short entry on the <a href="/docs/other/composables">composables page</a>; its API was already stable and is unchanged.</p><h3 id="settingsdialog-—-settingsbody-s-exposed-type" tabindex="-1">SettingsDialog — <code>SettingsBody</code>&#39;s exposed type <a class="header-anchor" href="#settingsdialog-—-settingsbody-s-exposed-type" aria-label="Permalink to “SettingsDialog — SettingsBody&#39;s exposed type”">​</a></h3><p><code>SettingsBody</code>&#39;s <code>viewportElement</code> expose now has a typed <code>SettingsBodyExposed</code> type (ADR-0012), exported from <code>frappe-ui</code>. No behavior change.</p><h3 id="fileuploader-—-uploads-default-to-private-security-fix-breaking" tabindex="-1">FileUploader — uploads default to private (security fix, breaking) <a class="header-anchor" href="#fileuploader-—-uploads-default-to-private-security-fix-breaking" aria-label="Permalink to “FileUploader — uploads default to private (security fix, breaking)”">​</a></h3><ul><li><strong>Silent break:</strong> <code>isPrivateUpload()</code> — the single resolver used by <code>useFileUpload</code> and <code>FileUploadHandler</code> — now defaults an upload with no stated <code>private</code> / <code>is_private</code> to <strong>private</strong>, not public. Previously <code>FileUploader</code> patched this default at the component level while <code>useFileUpload().upload(file, {})</code> and <code>new FileUploadHandler().upload(file, {})</code> resolved the same missing intent to public. The two disagreeing was <a href="https://github.com/frappe/frappe-ui/issues/922" target="_blank" rel="noreferrer">#922</a>; <code>FileUploader</code> itself already uploaded private (since <code>v1.0.0-beta.21</code>) and is unaffected. A caller of <code>useFileUpload</code> or <code>FileUploadHandler</code> with no explicit privacy option now gets a private file where it previously got a public one. See the <a href="/docs/migration#fileuploader">migration guide</a>.</li><li>Fixed: the standalone <code>upload(file, options)</code> export (re-exported from <code>frappe-ui</code> alongside <code>useFileUpload</code>) crashed at runtime — it required internal <code>state</code>/<code>reset</code> arguments the public signature never exposed a way to pass. It&#39;s now a real standalone function; <code>useFileUpload()</code> wraps it with reactive state.</li></ul><h3 id="fileuploader-—-flat-props-replace-the-uploadargs-blob-breaking-p3" tabindex="-1">FileUploader — flat props replace the <code>uploadArgs</code> blob (breaking, P3) <a class="header-anchor" href="#fileuploader-—-flat-props-replace-the-uploadargs-blob-breaking-p3" aria-label="Permalink to “FileUploader — flat props replace the uploadArgs blob (breaking, P3)”">​</a></h3><ul><li><strong>Silent break:</strong> <code>uploadArgs</code> is removed. Its fields that are actually used in the wild are now flat props: <code>private</code>, <code>folder</code>, <code>doctype</code>, <code>docname</code>, <code>fieldname</code>, <code>uploadEndpoint</code>, <code>optimize</code>. Old code keeps compiling — <code>uploadArgs</code> becomes an inert attribute on the root element — so an app that relied on it (<code>folder</code>, <code>doctype</code>, custom <code>private</code>, …) silently stops applying those options. Advanced options with no flat prop (<code>file_url</code>, <code>method</code>, <code>type</code>, <code>params</code>, <code>maxWidth</code>/<code>maxHeight</code>, upload cancellation) had zero measured use on the component (rule 9); reach for <code>useFileUpload()</code> directly for those. See the <a href="/docs/migration#fileuploader">migration guide</a>.</li></ul><h3 id="fileuploader-—-success-failure-emits-declared-stable" tabindex="-1">FileUploader — <code>success</code> / <code>failure</code> emits declared stable <a class="header-anchor" href="#fileuploader-—-success-failure-emits-declared-stable" aria-label="Permalink to “FileUploader — success / failure emits declared stable”">​</a></h3><ul><li>Both emits lost their <code>@deprecated</code> tag (ADR-0008 forbids shipping <code>@deprecated</code> members at <code>1.0.0</code>) and gained real types: <code>success: [data: UploadedFile]</code>, <code>failure: [error: unknown]</code> (previously untyped <code>any</code>). Both are load-bearing at real call sites and keep their names — they already read as behaviors (P1), not interactions.</li><li>Fixed: <code>failure</code> didn&#39;t fire when <code>validateFile</code> rejected a file — only on an actual upload error. <code>error</code> was set on the slot props either way, but a listener on <code>@failure</code> never heard about a validation rejection. It now emits <code>failure</code> with the validation error (string or <code>Error</code>) in both cases, matching what the type already promised.</li></ul><h3 id="fileuploader-—-slot-prop-error-is-now-always-a-string" tabindex="-1">FileUploader — slot prop <code>error</code> is now always a string <a class="header-anchor" href="#fileuploader-—-slot-prop-error-is-now-always-a-string" aria-label="Permalink to “FileUploader — slot prop error is now always a string”">​</a></h3><ul><li><strong>Silent break:</strong> <code>FileUploaderSlotProps.error</code> changed from <code>unknown</code> to <code>string | null</code>. Upload failures were already normalized to a message string; validation failures (<code>validateFile</code> returning an <code>Error</code>) were not — a custom slot could receive either a string or an <code>Error</code> object. Both paths now normalize to a message string before reaching the slot. A slot that did <span><code>{{ error.message }}</code></span> expecting the validation-<code>Error</code> case (uncommon, but not impossible) silently renders nothing now that <code>error</code> is always a string. See the <a href="/docs/migration#fileuploader">migration guide</a>.</li></ul><h3 id="fileuploader-—-inputref-removed-nothing-in-its-place" tabindex="-1">FileUploader — <code>inputRef</code> removed, nothing in its place <a class="header-anchor" href="#fileuploader-—-inputref-removed-nothing-in-its-place" aria-label="Permalink to “FileUploader — inputRef removed, nothing in its place”">​</a></h3><ul><li><strong>Breaking, loud:</strong> per <a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0012-template-ref-surface.md" target="_blank" rel="noreferrer">ADR-0012</a>, <code>FileUploader</code> hands back nothing through a template ref. <code>inputRef</code> was a function disguised as a ref (<code>uploader.value.inputRef().focus()</code>), and the <code>openFileSelector</code> slot prop already covers what it was used for. Zero known call sites.</li></ul><h3 id="fileuploader-—-structural-bar-typescript-types-ts-tests-docs" tabindex="-1">FileUploader — structural bar: TypeScript, <code>types.ts</code>, tests, docs <a class="header-anchor" href="#fileuploader-—-structural-bar-typescript-types-ts-tests-docs" aria-label="Permalink to “FileUploader — structural bar: TypeScript, types.ts, tests, docs”">​</a></h3><ul><li><code>FileUploader</code> is now fully typed (<code>FileUploaderProps</code>, <code>FileUploaderEmits</code>, <code>FileUploaderSlotProps</code> in <code>types.ts</code>), has <code>*.cy.ts</code> component tests covering the five at-bar behaviors, and a <code>data-slot=&quot;root&quot;</code> / <code>data-state=&quot;idle&quot; | &quot;uploading&quot; | &quot;success&quot; | &quot;error&quot;</code> pair for CSS hooks (P10). The default fallback trigger now renders validation/upload errors via <code>&lt;ErrorMessage&gt;</code> (<code>role=&quot;alert&quot;</code>) — previously invisible unless the caller used a custom slot.</li></ul><h3 id="filetobase64-and-the-filesize-helpers-—-unexported-from-root" tabindex="-1"><code>fileToBase64</code> and the <code>fileSize</code> helpers — unexported from root <a class="header-anchor" href="#filetobase64-and-the-filesize-helpers-—-unexported-from-root" aria-label="Permalink to “fileToBase64 and the fileSize helpers — unexported from root”">​</a></h3><ul><li><strong>Breaking, loud:</strong> <code>fileToBase64</code>, <code>formatBytes</code>, <code>getMaxFileSize</code>, and <code>fileSizeLimitMessage</code> are no longer exported from <code>frappe-ui</code>. Zero external call sites at the v1 sweep (rule 9) — all four stay as internal helpers shared by <code>useFileUpload</code>, <code>FileUploadHandler</code>, and the editor&#39;s media upload engine.</li></ul><h3 id="sidebar-—-deprecated-config-api-removed-breaking" tabindex="-1">Sidebar — deprecated config API removed (breaking) <a class="header-anchor" href="#sidebar-—-deprecated-config-api-removed-breaking" aria-label="Permalink to “Sidebar — deprecated config API removed (breaking)”">​</a></h3><p>Per ADR-0008, every member marked <code>@deprecated</code> is deleted. <code>Sidebar</code> is now a bare composable frame: <code>SidebarHeader</code> / <code>SidebarSection</code> / <code>SidebarLabel</code> / <code>SidebarItem</code> compose in the default slot, matching the direction agreed in <code>v1-release/plan.md</code>.</p><ul><li><strong>Breaking, silent:</strong> <code>Sidebar</code>&#39;s <code>header</code> and <code>sections</code> config-object props are gone. Old code still compiles — Vue drops them as inert attrs — but the sidebar renders empty instead of the configured header/sections. Compose <code>SidebarHeader</code> and <code>SidebarLabel</code> + <code>SidebarItem</code> (or <code>SidebarSection</code>) directly in the default slot.</li><li><strong>Breaking, silent:</strong> <code>Sidebar</code>&#39;s <code>#header-logo</code> and <code>#footer-items</code> slots are gone (they only existed to reach into the config-object layout). Old <code>&lt;template #header-logo&gt;</code> / <code>#footer-items&gt;</code> content stops rendering. Put that markup directly in the default slot instead.</li><li><strong>Breaking, silent:</strong> <code>SidebarSection</code>&#39;s <code>items</code> prop and <code>#sidebar-item</code> scoped slot are gone. It&#39;s now a plain collapsible-group wrapper — <code>label</code>, <code>collapsible</code>, <code>v-model:collapsed</code> — whose children are <code>SidebarItem</code>s composed directly in its default slot, instead of an <code>items</code> array plus a slot to customize each row.</li><li><strong>Breaking, silent:</strong> <code>SidebarItemProps.isActive</code> (alias for <code>active</code>) and <code>.condition</code> (config-object visibility filter) are gone. Use <code>active</code>; use <code>v-if</code> on the composed <code>SidebarItem</code> instead of <code>condition</code>.</li><li><strong>Breaking, silent:</strong> <code>SidebarHeader</code>&#39;s <code>#logo</code> slot is renamed to <code>#prefix</code> (P6 — no type-specific slot names when a generic one covers them). Old <code>&lt;template #logo&gt;</code> content stops rendering; the default logo/initial box shows instead.</li><li><code>SidebarItem</code>&#39;s collapsed-rail icon no longer swaps to a centered square and back while the sidebar&#39;s width animates — it holds one position through the transition (also fixes the icon sitting 2px off the rail&#39;s center line).</li><li><code>SidebarSection</code>&#39;s collapsible label is now a real <code>&lt;button&gt;</code> with <code>aria-expanded</code> / <code>aria-controls</code>, keyboard-operable (was a <code>&lt;div&gt;</code> with a click handler and no keyboard path).</li></ul><h3 id="listview-family-—-moved-to-frappe-ui-experimental-breaking" tabindex="-1">ListView family — moved to <code>frappe-ui/experimental</code> (breaking) <a class="header-anchor" href="#listview-family-—-moved-to-frappe-ui-experimental-breaking" aria-label="Permalink to “ListView family — moved to frappe-ui/experimental (breaking)”">​</a></h3><p><code>ListView</code> is not taken to bar at root for <code>1.0.0</code>. <code>frappe-ui/list</code> is the recommended primitive for new code, but it&#39;s a narrower, composition-based family by design — it has no equivalent for <code>ListView</code>&#39;s config-driven columns (resizable widths, per-column <code>getLabel</code>/<code>prefix</code> functions, cell tooltips, disabled-row exclusion, the built-in select banner). Rather than freeze the whole 12-export barrel at root undeprecated, it moves to <code>frappe-ui/experimental</code> (P14 — no stability promise) and stays there until <code>frappe-ui/list</code> reaches full functional parity.</p><ul><li><strong>Breaking, loud:</strong> <code>import { ListView, ... } from &#39;frappe-ui&#39;</code> fails to resolve. Import from <code>frappe-ui/experimental</code> instead: <code>List</code>, <code>ListView</code>, <code>ListEmptyState</code>, <code>ListFooter</code>, <code>ListGroupHeader</code>, <code>ListGroupRows</code>, <code>ListGroups</code>, <code>ListHeader</code>, <code>ListHeaderItem</code>, <code>ListRow</code>, <code>ListRowItem</code>, <code>ListRows</code>, <code>ListSelectBanner</code>.</li></ul><h3 id="texteditor-and-its-v0-exports-—-removed-from-root-breaking" tabindex="-1"><code>TextEditor</code> and its v0 exports — removed from root (breaking) <a class="header-anchor" href="#texteditor-and-its-v0-exports-—-removed-from-root-breaking" aria-label="Permalink to “TextEditor and its v0 exports — removed from root (breaking)”">​</a></h3><p>Per ADR-0008, the deprecated v0 editor exports are removed from top-level <code>frappe-ui</code> — loud breaks, the import fails to resolve:</p><ul><li><code>TextEditor</code>, <code>TextEditorBubbleMenu</code>, <code>TextEditorFixedMenu</code>, <code>TextEditorFloatingMenu</code>, <code>TextEditorContent</code>, <code>createEditorButton</code></li><li><code>ImageExtension</code>, <code>SetImageOptions</code>, <code>createSuggestionExtension</code>, <code>BaseSuggestionItem</code>, <code>CreateSuggestionExtensionOptions</code> (the two <code>TextEditor/extensions/*</code> barrels also re-exported from root)</li></ul><p>Use <a href="/docs/molecules/editor"><code>Editor</code></a> and its kits/building blocks from the <code>frappe-ui/editor</code> subpath instead — see the migration guide&#39;s <a href="/docs/migration#editor">Editor section</a>. This confirms <code>CONTEXT.md</code>&#39;s rule: the editor family is the only subsystem that exports from a subpath rather than root, and nothing editor-related is exported from root anymore.</p><p>The underlying v0 component files still ship, unmodified, as <code>frappe-ui/editor</code>&#39;s migration safety net. They are parked in <code>frappe-ui/experimental</code> (<code>experimental/TextEditor/</code>, #1007), so apps mid-migration keep an import path:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">TextEditor</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/experimental</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><p>This path is unstable — no deprecation window. Sharing the <code>experimental</code> barrel costs its other importers nothing in production: #870&#39;s rollup measurement shows unused re-export chains are pruned before <code>sideEffects</code> marking applies, so the editor graph is tree-shaken out of non-editor imports. Removing the files is a separate, human-gated cleanup once every consumer has migrated (spec/editor.md §12); the <code>TextEditor</code> public API redesign itself is out of scope for <code>1.0.0</code> and carved out to <code>1.1</code>.</p><h3 id="editor-and-texteditor-styles-—-tailwind-v4-theme-call-fixed" tabindex="-1">Editor and TextEditor styles — Tailwind v4 <code>theme()</code> call fixed <a class="header-anchor" href="#editor-and-texteditor-styles-—-tailwind-v4-theme-call-fixed" aria-label="Permalink to “Editor and TextEditor styles — Tailwind v4 theme() call fixed”">​</a></h3><p><code>.ProseMirror ul[data-type=&#39;taskList&#39;] input[type=&#39;checkbox&#39;]</code> used a Tailwind-v3-only <code>theme(&#39;colors.gray.900&#39;)</code> call in both <code>frappe-ui/editor</code>&#39;s and the v0 <code>TextEditor</code>&#39;s stylesheet, which broke Tailwind v4 builds (#861 — a remaining instance of #299). Replaced with the same <code>var(--ink-gray-9)</code> token the rest of both files already use.</p><h3 id="v1-resources-—-at-bar-exception-documented-listresource-gets-test-coverage" tabindex="-1">v1 resources — at-bar exception documented; <code>listResource</code> gets test coverage <a class="header-anchor" href="#v1-resources-—-at-bar-exception-documented-listresource-gets-test-coverage" aria-label="Permalink to “v1 resources — at-bar exception documented; listResource gets test coverage”">​</a></h3><p>v1 resources (<code>createResource</code>, <code>createListResource</code>, <code>createDocumentResource</code>, <code>getCachedResource</code>, <code>getCachedListResource</code>, <code>getCachedDocumentResource</code>, <code>resourcesPlugin</code>, <code>saveLocal</code>, <code>getLocal</code>, <code>deleteLocal</code>, <code>onDocUpdate</code>) ship un-deprecated and frozen at <code>1.0.0</code>, per #886. <a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0013-v1-resources-implementation-freeze.md" target="_blank" rel="noreferrer">ADR-0013</a> records the one exception: the implementation stays hand-written JavaScript rather than TypeScript, permanently — 344 production call sites make a rewrite riskier than the freeze. <code>createListResource</code>, the second-most-used export at 57 call sites, gets test coverage for the first time (<code>listResource.test.ts</code>): pagination, <code>insert</code>/<code>setValue</code> refreshing the list, caching, and <code>reload()</code>&#39;s pagination-state restore.</p><h3 id="tailwind-preset-—-content-export-added" tabindex="-1">Tailwind preset — <code>content</code> export added <a class="header-anchor" href="#tailwind-preset-—-content-export-added" aria-label="Permalink to “Tailwind preset — content export added”">​</a></h3><p><code>frappe-ui/tailwind</code> exports <code>content</code>, the glob list of frappe-ui source directories that emit Tailwind classes. Spread it into your app&#39;s <code>tailwind.config.js</code> <code>content</code> array instead of hand-maintaining the paths — see the new <a href="/docs/foundations/tailwind">Tailwind Setup</a> docs page. Tailwind v3 doesn&#39;t merge a preset&#39;s <code>content</code>, so this was previously unavoidable hand-maintenance, and it had already drifted: some apps on <code>frappe-ui@1.0.0-beta</code> glob <code>src/components/**</code> only, silently dropping every class the editor and list molecules emit.</p><h3 id="tailwind-preset-—-tokens-js-export-removed-breaking" tabindex="-1">Tailwind preset — <code>tokens.js</code> export removed (breaking) <a class="header-anchor" href="#tailwind-preset-—-tokens-js-export-removed-breaking" aria-label="Permalink to “Tailwind preset — tokens.js export removed (breaking)”">​</a></h3><p>The <code>./tailwind/tokens.js</code> export is removed outright, with no deprecation window. It had zero importers anywhere and re-exported <code>colorPalette.js</code> via <code>export *</code>, the implementation-module re-export pattern disallowed by P15. Use the preset (<code>frappe-ui/tailwind</code>) directly.</p><p>This ships before the <code>1.0.0</code> tag, while the library &quot;evolves freely&quot; (P13) — the freeze that requires a deprecation window starts at the tag, not before it. Zero call sites is also why it&#39;s a same-release removal rather than a carried-forward deprecation: there is no consumer for a warning to reach.</p><h3 id="tailwind-preset-—-unused-token-vocabulary-and-utilities-removed-breaking" tabindex="-1">Tailwind preset — unused token vocabulary and utilities removed (breaking) <a class="header-anchor" href="#tailwind-preset-—-unused-token-vocabulary-and-utilities-removed-breaking" aria-label="Permalink to “Tailwind preset — unused token vocabulary and utilities removed (breaking)”">​</a></h3><p>Design-token audit before the additive-only freeze (#940): every family in <code>tailwind/generated/*.json</code> and every utility/<code>--*</code> variable <code>plugin.js</code> emits was checked against frappe-ui&#39;s own source, docs, and stories, plus a fresh census of all consumer apps (crm, helpdesk, gameplan, insights, builder, suite, central, frappe_calendar, frappe-ui-starter, and frappe&#39;s <code>ui/</code> package). The primitive and semantic color ramps (all twelve hues, in <code>surface-*</code>/<code>ink-*</code>/<code>outline-*</code>), and every typography weight (including <code>bold</code>/<code>black</code>) and size through <code>text-12xl</code>, turned out to be real, in-use vocabulary — none of that is touched. What had zero call sites everywhere is removed:</p><ul><li><strong><code>text-tiny</code></strong> and its uppercase text-transform. Not even shown in the docs&#39; own type-scale page.</li><li><strong><code>text-13xl</code> through <code>text-16xl</code></strong> (and their <code>-medium</code>/<code>-semibold</code>/ <code>-bold</code>/<code>-black</code> variants). The docs&#39; own &quot;display sizes&quot; showcase stops at <code>text-12xl</code> — these four sizes were past what even the type-scale demo used.</li><li><strong><code>shadow-status</code></strong> and its backing <code>--elevation-status</code> variable. Named once in prose on the elevation docs page but never rendered there or anywhere else.</li><li><strong><code>surface-alert-button-*</code> / <code>ink-alert-button-*</code></strong> (<code>default</code>, <code>info</code>, <code>success</code>, <code>warning</code>, <code>error</code>). <code>Alert</code>&#39;s buttons color via the shared <code>variant</code>+<code>theme</code> axes (P4); this Figma spec never got wired to code.</li><li><strong><code>surface-alpha-gray-2-overlay</code></strong>. Resolved to the black/white overlay ramp rather than the gray-alpha ramp its name implies, breaking the <code>{family}-{step}</code> pattern every other <code>surface-alpha</code> entry follows.</li></ul><p>All five are silent breaks — a missing Tailwind class or <code>--*</code> var just stops applying, no build or type error. See the migration guide.</p><p>The token generator (<code>tailwind/figma-tokens-to-theme.js</code>) now filters these out at the source, so they stay gone on the next <code>yarn sync-tokens</code> run rather than reappearing. <code>ALPHA_FAMILIES</code> also dropped a dead <code>&#39;red-alpha&#39;</code> entry that never matched anything in the Figma export — no emitted token changed.</p><p><strong>Also removed:</strong> <code>tailwind/colors.js</code>, a 642-line legacy color module superseded by <code>colors.json</code> + <code>colorPalette.js</code>. It had zero importers and wasn&#39;t reachable through any <code>frappe-ui</code> package export (no <code>./tailwind/*</code> wildcard) — deleting it doesn&#39;t change anything for consumers.</p><h3 id="frappe-ui-vite-—-types-and-docs" tabindex="-1"><code>frappe-ui/vite</code> — types and docs <a class="header-anchor" href="#frappe-ui-vite-—-types-and-docs" aria-label="Permalink to “frappe-ui/vite — types and docs”">​</a></h3><p><code>frappe-ui/vite</code> now ships hand-written types (<code>vite/index.d.ts</code>, wired via the <code>types</code> export condition), so <code>frappeui(...)</code> and its options (<code>frontendRoute</code>, <code>lucideIcons</code>, <code>barrelImports</code>, <code>frappeProxy</code>, <code>jinjaBootData</code>, <code>buildConfig</code>, <code>frappeTypes</code>) are typed without a <code>// @ts-expect-error</code> workaround. Also added a <a href="/docs/other/vite">docs page</a> covering every sub-plugin, including <code>barrelImports</code> — previously undocumented on the docs site.</p><h3 id="list-style-css-and-editor-style-css-exports-—-removed" tabindex="-1">list-style.css and editor-style.css exports — removed <a class="header-anchor" href="#list-style-css-and-editor-style-css-exports-—-removed" aria-label="Permalink to “list-style.css and editor-style.css exports — removed”">​</a></h3><ul><li><strong>Breaking:</strong> the manual <code>frappe-ui/list-style.css</code> and <code>frappe-ui/editor-style.css</code> exports are gone (loud — the consumer build fails with <code>Missing &quot;./list-style.css&quot; specifier</code>). They existed only because bundlers tree-shook the side-effect <code>import &#39;./style.css&#39;</code> inside the <code>frappe-ui/list</code> and <code>frappe-ui/editor</code> barrels. The barrels are now listed in <code>sideEffects</code>, so each family&#39;s CSS ships automatically the moment you import anything from its subpath — delete the manual <code>@import</code> lines. The tree-shake was never Rolldown-specific: plain Rollup/Vite production builds dropped the CSS too.</li></ul><h3 id="toggles-and-ranged-inputs-—-deprecated-members-removed" tabindex="-1">Toggles and ranged inputs — deprecated members removed <a class="header-anchor" href="#toggles-and-ranged-inputs-—-deprecated-members-removed" aria-label="Permalink to “Toggles and ranged inputs — deprecated members removed”">​</a></h3><p>Per ADR-0008, the family&#39;s deprecated aliases are <strong>removed</strong>, not shipped frozen. All five had zero call sites across the consumer apps. These are silent breaks — old code compiles and runs, but the name is ignored (see the migration guide&#39;s Inputs table):</p><ul><li><code>Rating.rating_from</code> → <code>max</code>; <code>Rating.readonly</code> → <code>disabled</code>.</li><li><code>Switch.change</code> emit → <code>v-model</code> / <code>@update:modelValue</code>; <code>Switch.labelClasses</code> → <code>data-*</code> styling hooks.</li><li><code>Checkbox.padding</code> → <code>padded</code>.</li></ul><p><code>Slider</code> now exports its types (<code>SliderProps</code>, <code>SliderEmits</code>, <code>SliderValue</code>), and <code>Rating</code> exports <code>RatingEmits</code>.</p><h3 id="circularprogressbar-—-removed" tabindex="-1">CircularProgressBar — removed <a class="header-anchor" href="#circularprogressbar-—-removed" aria-label="Permalink to “CircularProgressBar — removed”">​</a></h3><ul><li><strong>Breaking:</strong> <code>CircularProgressBar</code> is no longer exported (loud — the import fails). It was a second component for <code>Progress</code>&#39;s concept (P8), with hardcoded light-mode colors and a structured <code>theme</code> object prop (P3/P4). One call site existed across all consumer apps. Use <code>Progress</code>, or copy the old SFC into your app if you need the radial form.</li></ul><h3 id="node-js-requirement" tabindex="-1">Node.js requirement <a class="header-anchor" href="#node-js-requirement" aria-label="Permalink to “Node.js requirement”">​</a></h3><ul><li><strong>Breaking:</strong> Node floor is now <code>&gt;=20.19.0</code> (was Node 18 on 0.1.x). Declared via <code>package.json</code> <code>engines</code> so installers and CI surface the requirement instead of opaque transitive-dep engine errors.</li></ul><h3 id="portal-target-for-embedded-apps" tabindex="-1">Portal target for embedded apps <a class="header-anchor" href="#portal-target-for-embedded-apps" aria-label="Permalink to “Portal target for embedded apps”">​</a></h3><ul><li><code>portalTo</code> on <code>Popover</code>, <code>HoverCard</code>, <code>Dropdown</code>, <code>Select</code>, <code>Combobox</code> and <code>MultiSelect</code> no longer declares a <code>&#39;body&#39;</code> prop default. An unembedded app still gets <code>&#39;body&#39;</code>, now as a fallback. No existing call behaves differently.</li><li>New <code>usePortalTarget</code> / <code>providePortalTarget</code> / <code>portalTargetKey</code> exports let an embedding host redirect every overlay at once. See <a href="https://github.com/frappe/frappe-ui/blob/main/spec/portal-target.md" target="_blank" rel="noreferrer"><code>spec/portal-target.md</code></a>.</li></ul><h3 id="dialog-—-v1-spec" tabindex="-1">Dialog — v1 spec <a class="header-anchor" href="#dialog-—-v1-spec" aria-label="Permalink to “Dialog — v1 spec”">​</a></h3><ul><li>Flat top-level props (<code>title</code>, <code>message</code>, <code>icon</code>, <code>size</code>, <code>position</code>, <code>paddingTop</code>, <code>actions</code>) are canonical. The legacy <code>options</code> blob is removed — see below.</li><li><code>v-model:open</code> is canonical; <code>v-model</code> (modelValue) still works silently.</li><li>New props: <code>dismissible</code> (default <code>true</code>, replaces <code>disableOutsideClickToClose</code>), <code>bare</code>, <code>showCloseButton</code> (default <code>true</code>, independent of the auto-header).</li><li>Canonical slots <code>#default</code>, <code>#title</code>, <code>#actions</code> (scoped with <code>{ close, actions }</code>). The legacy <code>#body*</code> slots are removed — see below.</li><li><code>icon.theme</code> (<code>yellow | blue | red | green</code>) replaces <code>icon.appearance</code>, which is removed — see below.</li><li>Auto-header no longer renders an &quot;Untitled&quot; fallback.</li></ul><h3 id="dialog-—-imperative-dialog-api" tabindex="-1">Dialog — imperative <code>dialog.*</code> API <a class="header-anchor" href="#dialog-—-imperative-dialog-api" aria-label="Permalink to “Dialog — imperative dialog.* API”">​</a></h3><ul><li>New callback-based helpers: <code>dialog.confirm()</code>, <code>dialog.danger()</code>, <code>dialog.prompt()</code>. The <code>onConfirm</code> callback runs on click; resolving auto-closes the dialog, while throwing keeps it open and renders the thrown message inline. The action button shows a loading state until <code>onConfirm</code> settles. Each helper also returns a synchronous handle with <code>close()</code> for programmatic dismissal.</li><li><code>&lt;FrappeUIProvider&gt;</code> now renders <code>&lt;Dialogs /&gt;</code> next to <code>&lt;Toasts /&gt;</code>, so apps wrapped with the provider get the imperative stack for free. <code>&lt;Dialogs /&gt;</code> is still exported for callers that don&#39;t use the provider.</li><li><code>ConfirmDialog</code> and <code>confirmDialog()</code> are removed — see below; use <code>dialog.confirm()</code> / <code>dialog.danger()</code>.</li><li>New root exports: <code>DangerArgs</code>, <code>DialogControl</code>, <code>PromptControl</code>, <code>DialogHandle</code>, <code>PromptFieldValidator</code>. <code>DialogSlotProps</code> is exported from the <code>Dialog</code> barrel.</li></ul><h3 id="dialog-—-deprecated-surface-removed-breaking" tabindex="-1">Dialog — deprecated surface removed (breaking) <a class="header-anchor" href="#dialog-—-deprecated-surface-removed-breaking" aria-label="Permalink to “Dialog — deprecated surface removed (breaking)”">​</a></h3><p>Every member marked <code>@deprecated</code> is deleted, per <a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0008-no-deprecated-members-in-1-0-0.md" target="_blank" rel="noreferrer">ADR-0008</a>. Nothing is aliased and nothing warns.</p><ul><li><strong>Breaking, silent:</strong> the <code>options</code> blob prop and <code>DialogOptions</code> type are gone. It bundled <code>title</code>/<code>size</code>/<code>icon</code>/<code>actions</code> into one object. An <code>:options=&quot;{...}&quot;</code> call site still compiles — Vue drops the unknown prop as an inert attr — but the dialog silently loses its title, size and actions. Use the flat top-level props.</li><li><strong>Breaking, silent:</strong> <code>disableOutsideClickToClose</code> is gone. It still lands as an inert attr, and <code>dismissible</code> (the inverse) defaults to <code>true</code>, so the dialog silently becomes dismissible. Use <code>dismissible</code>.</li><li><strong>Breaking, silent:</strong> <code>icon.appearance</code> and <code>DialogIconAppearance</code> are gone; only <code>icon.theme</code> remains. An <code>appearance</code> key is dropped, so the icon renders with no tone. Map <code>warning → yellow</code>, <code>info → blue</code>, <code>danger → red</code>, <code>success → green</code>.</li><li><strong>Breaking, silent:</strong> the legacy <code>#body</code>, <code>#body-content</code>, <code>#body-main</code>, <code>#body-title</code> and <code>#body-header</code> slots are gone. Vue drops an unknown named slot with no error, so a missed call site renders nothing where that slot&#39;s content used to be. Use <code>#default</code>, <code>#title</code> and <code>#actions</code>; <code>#body</code> maps to <code>bare</code> + <code>#default</code>.</li><li><strong>Breaking:</strong> the callable-context shim on action <code>onClick</code> is gone. The context used to be callable as well as a plain object (<code>ctx()</code> closed the dialog); it is <code>{ close }</code> only now, so calling it as a function throws <code>TypeError: ctx is not a function</code>.</li><li><strong>Breaking:</strong> <code>defineExpose({ close })</code> and the <code>DialogExposed</code> type are gone — Dialog exposes nothing on its template ref (ADR-0012). A template-ref <code>.close()</code> call throws a <code>TypeError</code>. Use <code>v-model:open = false</code>, or the <code>close</code> slot prop. Zero known call sites.</li><li><strong>Breaking:</strong> <code>ConfirmDialog</code> and <code>confirmDialog()</code> are deleted. The import fails, so the build names every call site. Use <code>dialog.confirm()</code> / <code>dialog.danger()</code>.</li></ul><p>Before/after for the silent breaks is in the <a href="/docs/migration#dialog">migration guide</a>.</p><h3 id="datepicker-family-—-v1-spec" tabindex="-1">DatePicker family — v1 spec <a class="header-anchor" href="#datepicker-family-—-v1-spec" aria-label="Permalink to “DatePicker family — v1 spec”">​</a></h3><p><code>DatePicker</code>, <code>DateRangePicker</code>, and <code>DateTimePicker</code> share the v1 popover-trigger vocabulary used by <code>Combobox</code> / <code>Dropdown</code> / <code>Select</code>.</p><ul><li><code>side</code> (default <code>&#39;bottom&#39;</code>) + <code>align</code> (default <code>&#39;start&#39;</code>) + <code>offset</code> (default <code>4</code>) replace <code>placement</code> (removed).</li><li><code>keepOpen</code> (default <code>false</code>) replaces <code>autoClose</code> (removed, inverse).</li><li><code>typeable</code> (default <code>true</code>) replaces picker-level <code>readonly</code> and <code>allowCustom</code> (both removed). <code>:typeable=&quot;false&quot;</code> blocks typing while keeping the popover interactive.</li><li>Constraints: <code>min?: string</code> and <code>max?: string</code> (<code>YYYY-MM-DD</code>, plus <code>YYYY-MM-DD HH:mm:ss</code> on <code>DateTimePicker</code>), and <code>isDateUnavailable?: (date: Dayjs) =&gt; boolean</code> for arbitrary disabling. Min/max and the predicate compose. On <code>DateTimePicker</code>, <code>minDateTime</code>/<code>maxDateTime</code> are removed in favor of <code>min</code>/<code>max</code>.</li><li><code>v-model:open</code> supported on all three pickers via <code>open</code> + <code>update:open</code>.</li><li><code>openOnFocus</code> (default <code>false</code>) and <code>openOnClick</code> (default <code>true</code>) let consumers opt out of either trigger path. Same defaults applied to <code>Combobox</code> for parity.</li><li><code>#trigger</code> is the canonical custom-trigger slot; <code>#target</code> is removed.</li><li><code>DateRangePicker.clearable</code> now defaults to <code>true</code>; footer hides when there is nothing to clear. Live hover preview while picking the end date and a stable trigger width derived from <code>format</code> were added in the same pass.</li><li>Public type exports added: <code>DateTimePickerProps</code>, <code>DateRangePickerEmits</code>, <code>DateTimePickerEmits</code>, <code>DateRangeValue</code>.</li></ul><h3 id="datepicker-family-—-daterangepicker-emit-shape-breaking" tabindex="-1">DatePicker family — <code>DateRangePicker</code> emit shape (breaking) <a class="header-anchor" href="#datepicker-family-—-daterangepicker-emit-shape-breaking" aria-label="Permalink to “DatePicker family — DateRangePicker emit shape (breaking)”">​</a></h3><p><code>DateRangePicker</code> emits <code>update:modelValue</code> / <code>change</code> as a <code>[from, to]</code> tuple (<code>DateRangeValue = [string, string] | []</code>) instead of a comma-joined string. The <code>modelValue</code> prop already accepted <code>string[]</code>; the emit is what changes.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// before</span></span>
<span class="line"><span class="s_50ecpt">function</span><span class="s_indoxt"> onChange</span><span class="s_13ahmt">(</span><span class="s_fsg3al">v</span><span class="s_2ekfrt">:</span><span class="s_i592pt"> string</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> { </span><span class="s_252irl">const</span><span class="s_1jjt6x"> [</span><span class="s_295sjd">from</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> to</span><span class="s_1jjt6x">]</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> v</span><span class="s_1jjt6x">.</span><span class="s_indoxt">split</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">,</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">) }</span></span>
<span class="line"><span class="s_1th9sy">// after</span></span>
<span class="line"><span class="s_50ecpt">function</span><span class="s_indoxt"> onChange</span><span class="s_13ahmt">(</span><span class="s_fsg3al">v</span><span class="s_2ekfrt">:</span><span class="s_euu481"> DateRangeValue</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> { </span><span class="s_252irl">const</span><span class="s_1jjt6x"> [</span><span class="s_295sjd">from</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> to</span><span class="s_1jjt6x">]</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> v</span><span class="s_13ahmt"> }</span><span class="s_1th9sy"> // [] when cleared</span></span></code></pre></div><p>Reactive forms that pass the value through unchanged are unaffected.</p><h3 id="datepicker-family-—-footer-removed-new-actions-sidebar-slot" tabindex="-1">DatePicker family — footer removed; new <code>#actions</code> sidebar slot <a class="header-anchor" href="#datepicker-family-—-footer-removed-new-actions-sidebar-slot" aria-label="Permalink to “DatePicker family — footer removed; new #actions sidebar slot”">​</a></h3><p>The dedicated popover footer on <code>DatePicker</code>, <code>DateRangePicker</code>, and <code>DateTimePicker</code> has been removed, including the auto-rendered Clear button that used to render there when <code>clearable &amp;&amp; hasValue</code>. <code>clearable</code> still governs the input-level clear affordance.</p><ul><li>New <code>#actions</code> slot renders as a <strong>left sidebar</strong> inside the popover. Slot props include <code>close</code>, <code>setDate</code> / <code>setRange</code>, and <code>clear</code>. <code>DateRangePicker</code>&#39;s <code>setRange([from, to])</code> commits both endpoints atomically — use it for fixed-window presets (&quot;Last 7 days&quot;).</li><li>Popover content is <code>w-fit</code> when the slot is provided.</li><li><code>data-slot=&quot;actions&quot;</code> is set on the sidebar <code>&lt;aside&gt;</code> for CSS hooks.</li></ul><p>Migration: callers who relied on the auto-rendered Clear button should render an explicit Clear row inside <code>#actions</code> using the <code>clear</code> slot prop.</p><h3 id="datetimepicker-—-date-selection-keeps-popover-open-breaking" tabindex="-1">DateTimePicker — date selection keeps popover open (breaking) <a class="header-anchor" href="#datetimepicker-—-date-selection-keeps-popover-open-breaking" aria-label="Permalink to “DateTimePicker — date selection keeps popover open (breaking)”">​</a></h3><p>Selecting a date in <code>DateTimePicker</code> no longer auto-closes the popover. Focus moves into the embedded <code>TimePicker</code> instead, so users get a continuous date → time flow. The popover closes on <code>Esc</code>, click-outside, or programmatic <code>close()</code>.</p><p>Migration: callers relying on the implicit close should bind <code>v-model:open</code> and close from <code>@update:modelValue</code>, or render an &quot;Apply&quot; button in <code>#actions</code> (which receives <code>close</code> in its slot scope).</p><h3 id="timepicker-—-v1-refresh" tabindex="-1">TimePicker — v1 refresh <a class="header-anchor" href="#timepicker-—-v1-refresh" aria-label="Permalink to “TimePicker — v1 refresh”">​</a></h3><p>Same vocabulary as the DatePicker family plus a flexible parser.</p><ul><li><code>side</code> / <code>align</code> / <code>offset</code> replace <code>placement</code> (removed).</li><li><code>keepOpen</code> (default <code>false</code>) replaces <code>autoClose</code> (removed).</li><li><code>typeable</code> (default <code>true</code>) replaces picker-level <code>readonly</code> / <code>allowCustom</code> (both removed).</li><li><code>v-model:open</code> via <code>open</code> + <code>update:open</code>; new <code>openOnFocus</code> (default <code>false</code>) and <code>openOnClick</code> (default <code>true</code>) props.</li><li>Flexible typed input: <code>&quot;3pm&quot;</code>, <code>&quot;3.30pm&quot;</code>, <code>&quot;1500&quot;</code>, <code>&quot;9:30:15 am&quot;</code> parse to canonical <code>HH:mm[:ss]</code>.</li><li><code>min</code> / <code>max</code> replace <code>minTime</code> / <code>maxTime</code> (removed).</li><li><code>scrollMode</code> is removed; list is always centered on the selection.</li><li>Template ref exposes only <code>focus()</code> (ADR-0012). <code>selectAll()</code> and <code>blurInput()</code>, dead members with no callers, are removed.</li></ul><h3 id="datepicker-family-—-keyboard-navigation" tabindex="-1">DatePicker family — keyboard navigation <a class="header-anchor" href="#datepicker-family-—-keyboard-navigation" aria-label="Permalink to “DatePicker family — keyboard navigation”">​</a></h3><p>Full keyboard nav inside the calendar grid (WAI-ARIA APG Date Picker Dialog spec).</p><ul><li><code>↓</code> on the trigger input opens the popover and moves focus to the selected/today cell.</li><li>Grid: <code>←</code>/<code>→</code> ±1 day, <code>↑</code>/<code>↓</code> ±1 week, <code>Home</code>/<code>End</code> week edges, <code>PageUp</code>/<code>PageDown</code> ±1 month, <code>Shift+PageUp</code>/<code>Shift+PageDown</code> ±1 year.</li><li><code>Enter</code> / <code>Space</code> selects. <code>Esc</code> closes and returns focus to the input.</li><li>Disabled dates (via <code>min</code> / <code>max</code> / <code>isDateUnavailable</code>) are skipped.</li><li>Arrow keys auto-advance across month boundaries.</li><li><code>DateRangePicker</code> dual-pane: arrow keys cross panes without advancing the view; range-hover shading tracks the keyboard-focused cell.</li></ul><p>Roving tabindex: exactly one cell is in the tab order, so <code>Tab</code> enters and leaves the grid as a single unit. Custom <code>#trigger</code> slots opt in automatically — any open path moves focus into the grid since a non-<code>TextInput</code> trigger has no typing context.</p><h3 id="datepicker-family-—-legacy-composable-removed" tabindex="-1">DatePicker family — legacy composable removed <a class="header-anchor" href="#datepicker-family-—-legacy-composable-removed" aria-label="Permalink to “DatePicker family — legacy composable removed”">​</a></h3><p><code>useDatePicker</code> and its helpers (<code>getDate</code>, <code>getDatesAfter</code>, <code>getDaysInMonth</code>, <code>isLeapYear</code>) were not used by any picker component and were not part of the v1 API. Deleted outright — the import fails, so the break is loud.</p><h3 id="datepicker-timepicker-family-—-deprecated-aliases-removed-adr-0008" tabindex="-1">DatePicker / TimePicker family — deprecated aliases removed (ADR-0008) <a class="header-anchor" href="#datepicker-timepicker-family-—-deprecated-aliases-removed-adr-0008" aria-label="Permalink to “DatePicker / TimePicker family — deprecated aliases removed (ADR-0008)”">​</a></h3><p>The back-compat aliases these components carried through the betas are deleted, not kept as warn-and-map shims — per <a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0008-no-deprecated-members-in-1-0-0.md" target="_blank" rel="noreferrer">ADR-0008</a>, no deprecated member ships in <code>1.0.0</code>. Before/afters in the <a href="/docs/migration#datepicker-timepicker-family">migration guide</a>.</p><ul><li><strong><code>placement</code>, <code>autoClose</code>, <code>allowCustom</code>, picker-level <code>readonly</code>, <code>inputClass</code>, <code>value</code> prop removed.</strong> All silent: a leftover prop lands as an inert extra attribute instead of doing anything.</li><li><strong><code>#target</code> slot removed.</strong> Content in a leftover <code>&lt;template #target&gt;</code> silently stops rendering. Use <code>#trigger</code>.</li><li><strong><code>DateTimePicker.minDateTime</code>/<code>maxDateTime</code> and <code>TimePicker.minTime</code>/<code>maxTime</code> removed.</strong> Silent: the constraint just stops being enforced. Use <code>min</code>/<code>max</code>.</li><li><strong><code>TimePicker.scrollMode</code> removed.</strong> Silent; the list is always centered.</li></ul><p><code>change</code> stays as a supported second emit alongside <code>update:modelValue</code> — it was never deprecated on <code>TimePicker</code>, and <code>DateTimePicker</code> depends on it internally, so removing it from the other two pickers would have been an inconsistent, unforced break.</p><h3 id="input-family-—-shared-labeling-contract" tabindex="-1">Input family — shared labeling contract <a class="header-anchor" href="#input-family-—-shared-labeling-contract" aria-label="Permalink to “Input family — shared labeling contract”">​</a></h3><p><code>TextInput</code>, <code>Textarea</code>, <code>Password</code>, <code>Checkbox</code>, <code>Switch</code>, <code>Rating</code>, and <code>Slider</code> accept <code>label</code>, <code>description</code>, <code>error</code>, <code>required</code>. Id is auto-generated; <code>&lt;label for&gt;</code>, <code>aria-describedby</code>, <code>aria-errormessage</code>, <code>aria-invalid</code>, <code>aria-required</code> are wired automatically. <code>error</code> accepts <code>string</code> or <code>Error</code> (with <code>Error.messages</code> rendered as stacked plain text). Existing call sites unchanged.</p><h3 id="input-family-—-data-styling-hooks" tabindex="-1">Input family — <code>data-*</code> styling hooks <a class="header-anchor" href="#input-family-—-data-styling-hooks" aria-label="Permalink to “Input family — data-* styling hooks”">​</a></h3><p>Every input shell renders the canonical <code>data-*</code> vocabulary so external CSS can target inputs without class-injection props:</p><ul><li><code>data-slot</code> (<code>&quot;label&quot;</code>, <code>&quot;control&quot;</code>, <code>&quot;description&quot;</code>, <code>&quot;error&quot;</code>)</li><li><code>data-size</code>, <code>data-variant</code> (where applicable)</li><li><code>data-state</code> (<code>&quot;valid&quot; | &quot;invalid&quot; | &quot;checked&quot; | &quot;unchecked&quot; | …</code>)</li><li><code>data-disabled</code>, <code>data-required</code></li></ul><h3 id="password-—-v-model-fix" tabindex="-1">Password — <code>v-model</code> fix <a class="header-anchor" href="#password-—-v-model-fix" aria-label="Permalink to “Password — v-model fix”">​</a></h3><p><code>Password</code> now uses <code>defineModel&lt;string&gt;()</code>, fixing the existing bug where <code>&lt;Password v-model&gt;</code> did not update from typing. Explicit <code>size</code>, <code>variant</code>, <code>disabled</code>, <code>placeholder</code>, <code>id</code>, <code>required</code> props replace <code>$attrs</code> routing.</p><h3 id="password-—-value-prop-removed-breaking" tabindex="-1">Password — <code>value</code> prop removed (breaking) <a class="header-anchor" href="#password-—-value-prop-removed-breaking" aria-label="Permalink to “Password — value prop removed (breaking)”">​</a></h3><p>Per <a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0008-no-deprecated-members-in-1-0-0.md" target="_blank" rel="noreferrer">ADR-0008</a>, no deprecated member ships in <code>1.0.0</code>. <code>value</code> warned and seeded <code>v-model</code> since it was deprecated earlier in this cycle; a census of every downstream app found zero call sites still passing it. Use <code>v-model</code> / <code>modelValue</code>.</p><h3 id="textinput-textarea-password-duration-—-focus-and-inputelement-on-the-ref" tabindex="-1">TextInput / Textarea / Password / Duration — <code>focus()</code> and <code>inputElement</code> on the ref <a class="header-anchor" href="#textinput-textarea-password-duration-—-focus-and-inputelement-on-the-ref" aria-label="Permalink to “TextInput / Textarea / Password / Duration — focus() and inputElement on the ref”">​</a></h3><p>Implements <a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0012-template-ref-surface.md" target="_blank" rel="noreferrer">ADR-0012</a>.</p><ul><li><strong>Breaking:</strong> <code>TextInput.el</code> and <code>Textarea.el</code> are renamed to <code>inputElement</code> — a computed, typed <code>HTMLInputElement | null</code> / <code>HTMLTextAreaElement | null</code>, never a raw ref.</li><li>All three, plus <code>Duration</code>, now expose <code>focus(options?: FocusOptions)</code>. <code>Password</code> previously exposed nothing.</li><li><code>TextInput</code>, <code>Textarea</code>, and <code>Password</code> share one exported type, <code>TextInputExposed</code>, from <code>TextInput</code>&#39;s <code>types.ts</code>.</li><li><code>DurationExposed.focus</code> gained the same <code>options?</code> parameter; its member set is unchanged.</li></ul><h3 id="rating-—-max-replaces-rating-from" tabindex="-1">Rating — <code>max</code> replaces <code>rating_from</code> <a class="header-anchor" href="#rating-—-max-replaces-rating-from" aria-label="Permalink to “Rating — max replaces rating_from”">​</a></h3><p>Default <code>5</code>. (The old name was kept as a deprecated alias during the betas and is now removed — see &quot;Toggles and ranged inputs&quot; above.) <code>Rating</code> no longer imports <code>FeatherIcon</code>; default star comes from <code>lucide-star</code> via the shared Tailwind plugin. Filled stars now render visibly for non-zero values.</p><h3 id="slider-—-additive-props-and-a11y-fix" tabindex="-1">Slider — additive props and a11y fix <a class="header-anchor" href="#slider-—-additive-props-and-a11y-fix" aria-label="Permalink to “Slider — additive props and a11y fix”">​</a></h3><ul><li><code>disabled</code> prop added.</li><li><code>size: &#39;sm&#39; | &#39;md&#39;</code> added; <code>&#39;md&#39;</code> scales track and thumb proportionally.</li><li>New <code>value-commit</code> emit fires when dragging ends (use for side-effects you don&#39;t want on every step).</li><li>Removed hardcoded <code>aria-label=&quot;Volume&quot;</code>. Labeling now flows through the shared contract; pass <code>label</code> explicitly. (Treated as a bug fix — every non-volume call site was announced as &quot;Volume&quot; by assistive tech.)</li><li>Visibility: visible track in collapsed wrappers, full-width by default.</li><li>Uncontrolled <code>Slider</code> initializes to <code>min</code> instead of rendering with no thumb.</li></ul><h3 id="switch-—-lucide-icons-deprecations" tabindex="-1">Switch — Lucide icons; deprecations <a class="header-anchor" href="#switch-—-lucide-icons-deprecations" aria-label="Permalink to “Switch — Lucide icons; deprecations”">​</a></h3><p>No longer imports <code>FeatherIcon</code>. <code>icon</code> is now <code>string | Component</code>; <code>lucide-*</code> strings route through the shared Tailwind plugin. <code>labelClasses</code> and the <code>change</code> emit were deprecated during the betas and are now removed (see &quot;Toggles and ranged inputs&quot; above). Row hover/active background removed.</p><h3 id="checkbox-—-padding-deprecated" tabindex="-1">Checkbox — <code>padding</code> deprecated <a class="header-anchor" href="#checkbox-—-padding-deprecated" aria-label="Permalink to “Checkbox — padding deprecated”">​</a></h3><p>In favor of <code>padded</code>. (Now removed — see &quot;Toggles and ranged inputs&quot; above.)</p><h3 id="textarea-—-ghost-variant-required-prop" tabindex="-1">Textarea — <code>ghost</code> variant; <code>required</code> prop <a class="header-anchor" href="#textarea-—-ghost-variant-required-prop" aria-label="Permalink to “Textarea — ghost variant; required prop”">​</a></h3><p><code>Textarea</code> now accepts the <code>&#39;ghost&#39;</code> variant (matching <code>TextInput</code> and <code>Password</code>) and the shared <code>required</code> prop.</p><h3 id="textinput-textarea-—-ghost-variant-paints-transparent-fix" tabindex="-1">TextInput / Textarea — <code>ghost</code> variant paints transparent (fix) <a class="header-anchor" href="#textinput-textarea-—-ghost-variant-paints-transparent-fix" aria-label="Permalink to “TextInput / Textarea — ghost variant paints transparent (fix)”">​</a></h3><p><code>ghost</code> set no <code>bg-*</code> class, so <code>@tailwindcss/forms</code> preflight painted the input <code>#fff</code> — a white pill in dark mode. <code>ghost</code> now sets <code>bg-transparent</code>, matching Combobox&#39;s own ghost search input. Closes #851.</p><h3 id="feathericon-—-removed-breaking" tabindex="-1">FeatherIcon — removed (breaking) <a class="header-anchor" href="#feathericon-—-removed-breaking" aria-label="Permalink to “FeatherIcon — removed (breaking)”">​</a></h3><p>Per <a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0008-no-deprecated-members-in-1-0-0.md" target="_blank" rel="noreferrer">ADR-0008</a>, the deprecated <code>FeatherIcon</code> component is deleted, along with the <code>feather-icons</code> dependency. <code>lucide-*</code> strings (or a <code>Component</code>) are the only supported icon forms now.</p><ul><li><strong>Breaking, loud:</strong> <code>import { FeatherIcon } from &#39;frappe-ui&#39;</code> and <code>&lt;FeatherIcon&gt;</code> fail at the import.</li><li><strong>Breaking, silent:</strong> every icon-name prop across the library (<code>Button.icon</code> / <code>iconLeft</code> / <code>iconRight</code>, <code>Dialog.icon</code>, <code>Dropdown</code> / <code>ContextMenu</code> item <code>icon</code>, <code>TabButtons</code> options <code>icon</code> / <code>iconLeft</code> / <code>iconRight</code>, <code>Icon.name</code>) used to fall back to <code>FeatherIcon</code> for a bare feather-style name (e.g. <code>&quot;edit&quot;</code>). That fallback is gone: an unrecognized string now renders nothing, with a dev-mode console warning once per (component, prop). Prefix the name with <code>lucide-</code>.</li></ul><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FeatherIcon</span><span class="s_1i4ay4"> name</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">plus</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">size-4</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> icon</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">plus</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- after --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">span</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">lucide-plus size-4</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> aria-hidden</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">true</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> icon</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">lucide-plus</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p>Hardcoded internal <code>FeatherIcon</code> usages across core components were migrated to <code>lucide-*</code> in this release.</p><p>Before/after for the silent break is in the <a href="/docs/migration#icons">migration guide</a>.</p><h3 id="input-—-removed-breaking" tabindex="-1">Input — removed (breaking) <a class="header-anchor" href="#input-—-removed-breaking" aria-label="Permalink to “Input — removed (breaking)”">​</a></h3><ul><li><strong>Breaking:</strong> <code>Input</code> and its <code>Input.cy.ts</code> tests are deleted. Per <a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0008-no-deprecated-members-in-1-0-0.md" target="_blank" rel="noreferrer">ADR-0008</a>, no deprecated member ships in <code>1.0.0</code>; a census of downstream apps found no live call sites left that render <code>&lt;Input&gt;</code> (five registrations were dead global component registrations, never rendered). Use <code>TextInput</code> for text-like modes, or <code>Textarea</code> / <code>Select</code> / <code>Checkbox</code> for the other type modes <code>Input</code> accepted.</li></ul><h3 id="card-listitem-standalone-toast-—-removed-breaking" tabindex="-1">Card, ListItem, standalone Toast — removed (breaking) <a class="header-anchor" href="#card-listitem-standalone-toast-—-removed-breaking" aria-label="Permalink to “Card, ListItem, standalone Toast — removed (breaking)”">​</a></h3><p>Per <a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0008-no-deprecated-members-in-1-0-0.md" target="_blank" rel="noreferrer">ADR-0008</a>, three unmaintained wrappers that shipped <code>@deprecated</code> in code are deleted, not carried forward. All three had zero call sites across the census of downstream apps.</p><ul><li><strong>Breaking:</strong> <code>Card</code> and its <code>.vue</code> file are removed. No drop-in replacement — rebuild the title/subtitle/actions/loading layout with plain markup, using <code>LoadingText</code> or <code>Skeleton</code> for the loading state.</li><li><strong>Breaking:</strong> <code>ListItem</code> and its <code>.vue</code> file are removed. No drop-in replacement — rebuild the title/subtitle/actions row with plain markup.</li><li><strong>Breaking:</strong> the standalone <code>Toast</code> SFC (<code>import { Toast } from &#39;frappe-ui&#39;</code>) is removed. This only affects direct usage of the raw <code>ToastRoot</code>-based component; the imperative API (<code>toast()</code> / <code>toast.success()</code> / <code>toast.error()</code> / <code>toast.info()</code>) and <code>&lt;ToastProvider&gt;</code> are unaffected and unchanged.</li></ul><p>All three fail loudly at the import. Before/after examples are in the <a href="/docs/migration#card-listitem-standalone-toast-removed">migration guide</a>.</p><h3 id="formlabel-—-moved-to-a-component-directory-non-breaking" tabindex="-1">FormLabel — moved to a component directory (non-breaking) <a class="header-anchor" href="#formlabel-—-moved-to-a-component-directory-non-breaking" aria-label="Permalink to “FormLabel — moved to a component directory (non-breaking)”">​</a></h3><p><code>FormLabel</code> now lives at <code>src/components/FormLabel/FormLabel.vue</code> instead of a bare <code>src/components/FormLabel.vue</code>, matching the rest of the input family. It gains <code>types.ts</code>, tests, stories, and a docs page. The import path for consumers (<code>import { FormLabel } from &#39;frappe-ui&#39;</code>) is unchanged.</p><h3 id="loadingindicator-loadingtext-—-moved-to-component-directories-non-breaking" tabindex="-1">LoadingIndicator / LoadingText — moved to component directories (non-breaking) <a class="header-anchor" href="#loadingindicator-loadingtext-—-moved-to-component-directories-non-breaking" aria-label="Permalink to “LoadingIndicator / LoadingText — moved to component directories (non-breaking)”">​</a></h3><p>Same move as <code>FormLabel</code>, for the same reason: both now live at <code>src/components/LoadingIndicator/</code> and <code>src/components/LoadingText/</code> instead of bare <code>.vue</code> files directly under <code>src/components/</code>. Each gains <code>types.ts</code> (<code>LoadingIndicatorProps</code>, <code>LoadingTextProps</code>), stories, a docs page, and cypress tests. The import path for consumers (<code>import { LoadingIndicator, LoadingText } from &#39;frappe-ui&#39;</code>) is unchanged.</p><p>Kept as distinct components from <code>Spinner</code> and <code>Skeleton</code> (P8) — usage data across the consumer census shows real, separate demand: <code>LoadingIndicator</code> (~60 files) and <code>LoadingText</code> (~11 files) are both load-bearing, not redundant overlap.</p><h3 id="icon-—-docs-page-and-stories-added" tabindex="-1">Icon — docs page and stories added <a class="header-anchor" href="#icon-—-docs-page-and-stories-added" aria-label="Permalink to “Icon — docs page and stories added”">​</a></h3><p><code>Icon</code> had no <code>stories/</code> folder, so it did not appear in the docs site despite being a public export. It now has a docs page and two stories (lucide string form, and the <code>Component</code> escape hatch).</p><h3 id="monthpicker-—-removed-breaking" tabindex="-1">MonthPicker — removed (breaking) <a class="header-anchor" href="#monthpicker-—-removed-breaking" aria-label="Permalink to “MonthPicker — removed (breaking)”">​</a></h3><p><code>MonthPicker</code> and its whole barrel (<code>MonthPicker.vue</code>, types, stories) are deleted. It duplicated <code>Select</code> for a narrower case. Use <code>Select</code> with month options — see the <a href="/docs/migration#monthpicker">migration guide</a>. The import fails, so the break is loud.</p><h3 id="legacy-components-—-dev-mode-warnings" tabindex="-1">Legacy components — dev-mode warnings <a class="header-anchor" href="#legacy-components-—-dev-mode-warnings" aria-label="Permalink to “Legacy components — dev-mode warnings”">​</a></h3><p><code>Pill</code> is no longer exported from the package entrypoint. It remains an internal <code>TabButtons</code> detail.</p><p><code>ThemeSwitcher</code> remains exported for v1 compatibility, but is deprecated. For new theme switchers, compose <code>Select</code> with the <code>useColorScheme</code> composable.</p><h3 id="autocomplete-—-removed-breaking" tabindex="-1">Autocomplete — removed (breaking) <a class="header-anchor" href="#autocomplete-—-removed-breaking" aria-label="Permalink to “Autocomplete — removed (breaking)”">​</a></h3><ul><li><strong>Breaking:</strong> <code>Autocomplete</code> and its <code>AutocompleteProps</code> type are deleted. Use <code>Combobox</code> for one value and <code>MultiSelect</code> for several. The import fails, so the build names every call site. <code>trigger=&quot;button&quot;</code> on either replacement is the shape <code>Autocomplete</code>&#39;s default target had: a button showing the selection, with the search box inside the popover.</li><li><strong>Breaking, silent:</strong> <code>FormControl type=&quot;autocomplete&quot;</code> is removed. The dispatcher falls through to <code>TextInput</code> and still forwards the type, so the result is <code>&lt;input type=&quot;autocomplete&quot;&gt;</code> — a plain text box, with no build or runtime error. A dev-only <code>console.error</code> names the removal.</li><li><strong>Breaking, silent:</strong> the <code>v-model</code> payload inverts. <code>Autocomplete</code> modelled the whole option object; both replacements model the value only. Listen to <code>@update:selectedOption</code> where the whole option is needed.</li><li><strong>Breaking, silent:</strong> <code>#target</code>&#39;s <code>open</code> slot prop was the <em>function</em> that opened the popover; <code>#trigger</code>&#39;s <code>open</code> is the open <em>state</em>. Anything reading it as a value (<code>v-if=&quot;open&quot;</code>) was always truthy and now is not.</li><li><code>#target</code> → <code>#trigger</code> otherwise: <code>Combobox</code> and <code>MultiSelect</code> attach the open toggle to the trigger element themselves, so drop the click handler. A <code>togglePopover()</code> carried through the rename throws on click — the popover still opens, so it reads as working while logging an error.</li><li>Grouped options use <code>{ group, options }</code>, not <code>{ group, items }</code>. Both normalizers now throw naming the group and the rename, rather than dying inside a <code>map</code> call.</li></ul><p>Before/after for each silent break is in the <a href="/docs/migration#autocomplete-removed">migration guide</a>.</p><h3 id="dropdown-contextmenu-—-deprecated-members-removed-adr-0008" tabindex="-1">Dropdown / ContextMenu — deprecated members removed (ADR-0008) <a class="header-anchor" href="#dropdown-contextmenu-—-deprecated-members-removed-adr-0008" aria-label="Permalink to “Dropdown / ContextMenu — deprecated members removed (ADR-0008)”">​</a></h3><p>Three surfaces that shipped as deprecated aliases in the betas are deleted, not aliased. All three are <strong>silent breaks</strong> in plain-JS apps — before/afters in the <a href="/docs/migration#dropdown-and-contextmenu">migration guide</a>; TypeScript callers get compile errors (the removed keys stay typed as <code>never</code>), and a dev-mode console warning fires when the old shape reaches the menu at runtime.</p><ul><li><strong><code>placement</code> prop and <code>DropdownPlacement</code> type removed.</strong> Use <code>align</code> (<code>left</code>→<code>start</code>, <code>center</code>→<code>center</code>, <code>right</code>→<code>end</code>). A leftover <code>placement</code> is ignored and the menu falls back to <code>align=&quot;start&quot;</code>.</li><li><strong><code>{ group, items }</code> removed.</strong> Use <code>{ group, options }</code>, matching <code>Combobox</code> / <code>MultiSelect</code> / <code>Select</code>. A leftover <code>items</code> group renders as an empty menu.</li><li><strong><code>component:</code> option rows removed</strong> (<code>DropdownComponentOption</code>, <code>ContextMenuComponentOption</code>). Use <code>slots: { item: fn }</code>. A leftover <code>component:</code> row renders as a plain action row off its <code>label</code>.</li></ul><p>Also removed: the <strong><code>DropdownExposed</code> type</strong> — it described a <code>close()</code> template-ref member that <code>Dropdown</code> never implemented ([ADR-0012] keeps <code>Dropdown</code>&#39;s template-ref surface empty; <code>v-model:open</code> and the <code>close</code> slot prop cover it). Type-only, so the break is loud.</p><h3 id="dropdown-—-disabled-state-reaches-the-menu-primitive" tabindex="-1">Dropdown — disabled state reaches the menu primitive <a class="header-anchor" href="#dropdown-—-disabled-state-reaches-the-menu-primitive" aria-label="Permalink to “Dropdown — disabled state reaches the menu primitive”">​</a></h3><p>The trigger now forwards its disabled state (from <code>button.disabled</code> or a <code>disabled</code> fallthrough attribute) to the underlying menu primitive. Previously only the generated <code>Button</code> was natively disabled; a custom trigger slot with a <code>disabled</code> attribute could still open the menu via keyboard or synthetic clicks.</p><h3 id="select-—-item-slot-prop-renamed-to-item" tabindex="-1">Select — <code>#item-*</code> slot prop renamed to <code>item</code> <a class="header-anchor" href="#select-—-item-slot-prop-renamed-to-item" aria-label="Permalink to “Select — #item-* slot prop renamed to item”">​</a></h3><p><code>#item-prefix</code>, <code>#item-label</code>, and <code>#item-suffix</code> on <code>Select</code> expose <code>item</code> as the canonical scoped binding, matching <code>Combobox</code> and <code>MultiSelect</code>. The previous <code>option</code> key is removed with the rest of the deprecated surface (ADR-0008) — destructuring <code>{ option }</code> yields <code>undefined</code>, silently. No runtime warning is possible (slot-prop destructuring isn&#39;t detectable), so grep for <code>#item-</code> slots destructuring <code>option</code>.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Select</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">people</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #item-prefix=&quot;{ option }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Avatar :image=&quot;option.image&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Select</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- after --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Select</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">people</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #item-prefix=&quot;{ item }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Avatar :image=&quot;item.image&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Select</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h3 id="combobox-—-trigger-sizing-matches-select" tabindex="-1">Combobox — trigger sizing matches Select <a class="header-anchor" href="#combobox-—-trigger-sizing-matches-select" aria-label="Permalink to “Combobox — trigger sizing matches Select”">​</a></h3><p>Root renders as a transparent layout box so the trigger sizes like <code>Select</code> in flex/grid containers. Query decoupled from model in button mode.</p><h3 id="combobox-multiselect-—-suffix-slot-replaces-the-chevron" tabindex="-1">Combobox / MultiSelect — <code>#suffix</code> slot replaces the chevron <a class="header-anchor" href="#combobox-multiselect-—-suffix-slot-replaces-the-chevron" aria-label="Permalink to “Combobox / MultiSelect — #suffix slot replaces the chevron”">​</a></h3><p>New <code>#suffix</code> slot on <code>Combobox</code> (input and button modes) and <code>MultiSelect</code>, mirroring the existing slot on <code>Select</code>. Providing the slot replaces the default chevron — render an explicit chevron fallback when your content is conditional. Canonical use is an inline clear button. See <code>Combobox/stories/Clearable.vue</code>.</p><h3 id="combobox-—-condition-authoritative-for-type-custom-rows" tabindex="-1">Combobox — <code>condition</code> authoritative for <code>type: &#39;custom&#39;</code> rows <a class="header-anchor" href="#combobox-—-condition-authoritative-for-type-custom-rows" aria-label="Permalink to “Combobox — condition authoritative for type: &#39;custom&#39; rows”">​</a></h3><p>A custom row&#39;s <code>condition({ query })</code> is now consulted even before the user types since opening, so it can fully gate its own visibility based on selection state and the typed query. Selectable rows are unchanged. This makes &quot;create new&quot; patterns expressible directly via <code>condition</code>, with no need for a dedicated <code>createOption</code> prop. See <code>Combobox/stories/CreateNew.vue</code>.</p><h3 id="multiselect-—-summary-suppresses-the-phantom-sizer" tabindex="-1">MultiSelect — <code>#summary</code> suppresses the phantom sizer <a class="header-anchor" href="#multiselect-—-summary-suppresses-the-phantom-sizer" aria-label="Permalink to “MultiSelect — #summary suppresses the phantom sizer”">​</a></h3><p>The trigger&#39;s default behavior pins a minimum width derived from the worst-case default summary (<code>placeholder</code> vs <code>&quot;N selected&quot;</code>) so the trigger doesn&#39;t jitter as the count changes. That sizer can&#39;t predict custom text, so it&#39;s now skipped when <code>#summary</code> is provided — the trigger becomes content-sized and the consumer owns the width.</p><h3 id="inputlabel-—-slot-polish" tabindex="-1">InputLabel — slot polish <a class="header-anchor" href="#inputlabel-—-slot-polish" aria-label="Permalink to “InputLabel — slot polish”">​</a></h3><p>The default required indicator is not rendered when <code>#label</code> is used (slot receives <code>{ required }</code>). The labeling wrapper is dropped entirely when there is nothing to label.</p><h3 id="popover-—-v0-api-removed-breaking" tabindex="-1">Popover — v0 API removed (breaking) <a class="header-anchor" href="#popover-—-v0-api-removed-breaking" aria-label="Permalink to “Popover — v0 API removed (breaking)”">​</a></h3><p>Every member marked <code>@deprecated</code> is deleted, per <a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0008-no-deprecated-members-in-1-0-0.md" target="_blank" rel="noreferrer">ADR-0008</a>. Nothing is aliased and nothing warns.</p><ul><li><strong>Breaking, silent:</strong> the <code>#target</code>, <code>#body</code> and <code>#body-main</code> slots are gone. Vue drops an unknown slot without an error, so a missed call site renders a popover with no trigger, or an empty one. Use <code>#trigger</code> and <code>#default</code>.</li><li><strong>Breaking, silent:</strong> <code>#trigger</code> wires the click itself through reka&#39;s <code>PopoverTrigger</code>. A click handler carried over from <code>#target</code> toggles the popover a second time, so it opens and shuts on one click.</li><li><strong>Breaking, silent:</strong> the <code>togglePopover</code> and <code>updatePosition</code> slot props are gone. <code>toggle</code> replaces the first; reka repositions on its own, so the second has no replacement.</li><li><strong>Breaking, silent:</strong> <code>placement</code>, <code>show</code>, <code>hideOnBlur</code>, <code>matchTargetWidth</code>, <code>trigger</code>, <code>hoverDelay</code>, <code>leaveDelay</code>, <code>popoverClass</code> and <code>transition</code> are removed, and the <code>update:show</code> emit no longer fires. An unknown prop is ignored, so the popover renders in its default position and state.</li><li><strong>Breaking, silent:</strong> attributes on <code>&lt;Popover&gt;</code> are no longer inherited. They used to land on a wrapper the legacy <code>#target</code> rendered; <code>#trigger</code> is as-child and renders no wrapper. Move <code>class</code> and <code>style</code> onto the element inside <code>#trigger</code>.</li><li><strong>Breaking:</strong> the <code>PopoverPlacement</code> and <code>PopoverLegacySlotProps</code> types are removed. Use <code>PopoverSide</code> + <code>PopoverAlign</code> and <code>PopoverSlotProps</code>. The import fails, so the build names every call site.</li><li>Fixed: <code>CalendarWeekDayEvent</code> passed <code>placement=&quot;center&quot;</code> in month view, which is not a side and reached reka as one. It is <code>side=&quot;bottom&quot;</code> + <code>align=&quot;center&quot;</code> now.</li><li><strong>Breaking, silent:</strong> the slot props are <code>{ open, close, toggle }</code>. <code>open</code> is now the boolean state, matching <code>Dropdown</code>, <code>Select</code>, <code>MultiSelect</code>, <code>HoverCard</code> and <code>Sidebar</code>; the <code>open()</code> method it used to be had no callers, since <code>#trigger</code> opens itself. <code>isOpen</code> is gone — read <code>open</code> instead. A destructured <code>isOpen</code> becomes <code>undefined</code> with no error, so styling that depends on it stops applying silently.</li><li>Fixed: <code>MonthPicker</code> styled its panel through <code>popoverClass</code>, which had already become a no-op, so the panel rendered with no surface at all. It uses the standard panel shell now.</li><li>Fixed: <code>:dismissible=&quot;false&quot;</code> still closed on <code>Escape</code>. Only the outside-click channel was wired, while <code>CONTEXT.md</code> defines <code>dismissible</code> as covering both.</li></ul><p>Before/after for each silent break is in the <a href="/docs/migration#popover-hovercard-tooltip">migration guide</a>.</p><h3 id="nestedpopover-—-removed-breaking" tabindex="-1">NestedPopover — removed (breaking) <a class="header-anchor" href="#nestedpopover-—-removed-breaking" aria-label="Permalink to “NestedPopover — removed (breaking)”">​</a></h3><ul><li><strong>Breaking:</strong> <code>NestedPopover</code> is deleted. Use <code>Popover</code>. It never nested anything, and it was the library&#39;s last <code>@headlessui/vue</code> + <code>@popperjs/core</code> popover — <code>@popperjs/core</code> leaves <code>dependencies</code> with it. The import fails, so the build names every call site.</li></ul><h3 id="tooltip-—-vocabulary-aligned-with-popover-and-hovercard-breaking" tabindex="-1">Tooltip — vocabulary aligned with Popover and HoverCard (breaking) <a class="header-anchor" href="#tooltip-—-vocabulary-aligned-with-popover-and-hovercard-breaking" aria-label="Permalink to “Tooltip — vocabulary aligned with Popover and HoverCard (breaking)”">​</a></h3><ul><li><strong>Breaking, silent:</strong> <code>placement</code> is renamed to <code>side</code>, matching <code>Popover</code> and <code>HoverCard</code>. An unknown prop is ignored, so the tooltip keeps working and points at its default side.</li><li><strong>Breaking, silent:</strong> <code>arrowClass</code> is removed (P10 — no class-injection props). Style the arrow through <code>[data-slot=&quot;arrow&quot;]</code>. It was documented as the arrow&#39;s fill but was mostly used to nudge the bubble&#39;s position, which the new <code>offset</code> prop does directly.</li><li>Added: <code>offset</code> sets the gap in px between trigger and bubble, matching <code>Popover</code> and <code>HoverCard</code>. The bubble is no longer pinned at 4px.</li><li>Added: <code>[data-slot=&quot;content&quot;]</code>, <code>[data-slot=&quot;bubble&quot;]</code> and <code>[data-slot=&quot;arrow&quot;]</code> styling hooks.</li><li><strong>Breaking, silent:</strong> the <code>#body</code> slot is replaced by <code>#content</code>, which renders <em>inside</em> the bubble instead of replacing it. <code>#body</code> is not in P6&#39;s slot vocabulary, and it was the wrong shape: it stripped the bubble&#39;s surface, so six of the seven call sites in the apps hand-copied <code>rounded bg-surface-gray-10 px-2 py-1 text-xs text-ink-base shadow-xl</code> to put it back. Moving to <code>#content</code> usually means deleting that wrapper. Vue drops an unknown slot without an error, so a missed call site shows an empty tooltip.</li><li>Added: <code>bare</code> renders <code>#content</code> without the bubble shell, for content that brings its own surface — an image preview, say. The arrow still renders. This is the honest form of what <code>#body</code> was reached for.</li><li><code>TooltipBubble</code> is no longer exported. It is the internal bubble shared by <code>Tooltip</code> and <code>Button</code>, with no call sites outside the library.</li><li><code>Tooltip</code> keeps <code>#default</code> as the <strong>trigger</strong>, deliberately. It is the one inversion in the library, recorded under P6: over 200 call sites use the <code>&lt;Tooltip text=&quot;…&quot;&gt;&lt;Button /&gt;&lt;/Tooltip&gt;</code> shorthand, and renaming the slot would move every one of them for no behavioral gain.</li></ul><p>Before/after is in the <a href="/docs/migration#tooltip">migration guide</a>.</p><h3 id="hovercard-—-open-and-close-on-the-template-ref" tabindex="-1">HoverCard — <code>open()</code> and <code>close()</code> on the template ref <a class="header-anchor" href="#hovercard-—-open-and-close-on-the-template-ref" aria-label="Permalink to “HoverCard — open() and close() on the template ref”">​</a></h3><ul><li>Added: <code>open()</code> and <code>close()</code> on the component instance, matching <code>Popover</code>.</li><li>The trigger slot&#39;s props are now typed (<code>HoverCardSlotProps</code>) instead of <code>any</code>.</li></ul><h3 id="bottomsheet-—-focus-stays-inside-an-open-sheet" tabindex="-1">BottomSheet — focus stays inside an open sheet <a class="header-anchor" href="#bottomsheet-—-focus-stays-inside-an-open-sheet" aria-label="Permalink to “BottomSheet — focus stays inside an open sheet”">​</a></h3><p>The sheet opts out of autofocusing its first field, so it does not pop the keyboard on a phone. That also left focus on the trigger behind the overlay, with nothing holding it — <code>Tab</code> walked the page behind an open modal. The sheet now takes focus itself on open. The keyboard still stays down.</p><h3 id="divider-—-action-handler-removed-breaking" tabindex="-1">Divider — <code>action.handler</code> removed (breaking) <a class="header-anchor" href="#divider-—-action-handler-removed-breaking" aria-label="Permalink to “Divider — action.handler removed (breaking)”">​</a></h3><p>Per <a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0008-no-deprecated-members-in-1-0-0.md" target="_blank" rel="noreferrer">ADR-0008</a>, <code>action.handler</code> is deleted, not carried forward as a warning. Use <code>action.onClick</code>. Zero call sites across the census. Silent break — a leftover <code>handler</code> is dropped as an unknown key, so the action button renders but does nothing on click. Action mode preserves separator semantics for assistive technologies.</p><h3 id="pageheaderbackbutton-—-to-is-now-a-fallback-breaking" tabindex="-1">PageHeaderBackButton — <code>to</code> is now a fallback (breaking) <a class="header-anchor" href="#pageheaderbackbutton-—-to-is-now-a-fallback-breaking" aria-label="Permalink to “PageHeaderBackButton — to is now a fallback (breaking)”">​</a></h3><p><code>to</code> used to be the destination. Setting it made every tap push that route. It is now used only when there is no in-app history to go back to, such as a cold load onto a deep link. Every other tap goes back through history.</p><p>A back button that always lands on one fixed route is not a back button. It drops the user wherever the page author guessed they came from, which is wrong for every other way into the page.</p><p>Migration: nothing to do if <code>to</code> already named the page users came from. It now applies only on a cold load. If you need an unconditional push, use a plain <code>Button</code> with your own <code>router.push</code>.</p><h3 id="editor-—-media-captions-moved-off-alt-breaking" tabindex="-1">Editor — media captions moved off <code>alt</code> (breaking) <a class="header-anchor" href="#editor-—-media-captions-moved-off-alt-breaking" aria-label="Permalink to “Editor — media captions moved off alt (breaking)”">​</a></h3><p>Text in an image&#39;s or video&#39;s <code>alt</code> no longer renders as a caption. Captions live in a separate <code>caption</code> attribute, serialised as <code>data-caption</code>. <code>alt</code> goes back to being the screen reader description only.</p><p>Existing <code>alt</code> values still parse and still round-trip untouched. They just do not display as a caption any more.</p><p>The editor no longer edits <code>alt</code> at all. The caption field used to write it; it now writes <code>caption</code>, and no other control took over <code>alt</code>. Set it from your own content pipeline until an alt field lands.</p><p>There is deliberately no fallback from <code>caption</code> to <code>alt</code>. Stored <code>alt</code> values are mostly upload filenames and emoji shortcodes, and a real caption cannot be told apart from those automatically. Showing all of them is worse than showing none.</p><p>Migration: to keep a caption visible, copy the text into <code>caption</code>. A one-off content migration can do that where you know the old <code>alt</code> values were captions.</p><h3 id="http-transport-—-four-paths-collapse-to-one-breaking" tabindex="-1">HTTP transport — four paths collapse to one (breaking) <a class="header-anchor" href="#http-transport-—-four-paths-collapse-to-one-breaking" aria-label="Permalink to “HTTP transport — four paths collapse to one (breaking)”">​</a></h3><p><code>frappeRequest</code> is the single transport. Removed from the root export:</p><ul><li><strong><code>request</code></strong> — the bare <code>fetch</code> wrapper under <code>frappeRequest</code>, now internal. Use <code>frappeRequest</code>.</li><li><strong><code>createCall</code></strong> — no consumers in any app.</li><li><strong><code>initSocket</code></strong> — no consumers in any app; every one defines its own. <code>socket.io-client</code> remains a dependency (<code>resources/realtime.ts</code> exports functions typed against its <code>Socket</code>).</li></ul><p>All three are build failures at the import.</p><p><strong><code>call</code> now honours <code>setConfig</code> (silent).</strong> It kept its <code>(method, args, options)</code> signature, the value it resolves to, and the <code>{ response, status, error }</code> shape it hands <code>onError</code>, but it delegates to <code>frappeRequest</code> instead of building its own <code>fetch</code>. It had never imported <code>getConfig</code>, so <code>requestBaseUrl</code> and <code>requestHeaders</code> were ignored on every <code>call()</code> while <code>frappeRequest</code> respected them. Two consequences in apps that set either: <code>call</code> now goes to the configured base URL with <code>credentials: &#39;include&#39;</code>, and <code>_server_messages</code> from a <code>call</code> now reach <code>serverMessagesHandler</code>.</p><p><strong><code>FrappeRequestError</code> is now exported.</strong> <code>frappeRequest</code> threw it but nothing exported it, so a consumer could not type a <code>catch</code>.</p><h3 id="frapperequest-—-onerror-fired-twice-per-failure-fix" tabindex="-1"><code>frappeRequest</code> — <code>onError</code> fired twice per failure (fix) <a class="header-anchor" href="#frapperequest-—-onerror-fired-twice-per-failure-fix" aria-label="Permalink to “frappeRequest — onError fired twice per failure (fix)”">​</a></h3><p><code>request()</code> attached <code>transformError</code> with a trailing <code>.catch</code>, which also caught what <code>transformResponse</code> threw. Every failed HTTP response therefore ran <code>onError</code> twice. It now runs once, because <code>frappeRequest</code> marks an error it has already reported rather than because the rejection handler sees less. That distinction matters: an <em>ok</em> response whose body will not parse — Frappe answers an expired session with 200 and its login page, so <code>response.json()</code> throws — is a failure only that handler sees, and it still reaches <code>onError</code>.</p><p><strong>A method name starting with <code>http</code> skipped the <code>/api/method/</code> prefix (fix).</strong> The absolute-URL check was <code>url.startsWith(&#39;http&#39;)</code>, which matches the four letters rather than a scheme, so <code>http_utils.api.run</code> was fetched as a relative path. It now matches <code>https?://</code>.</p><p><code>frappeRequest</code> also gained an explicit return type and passes its type argument through, so <code>frappeRequest&lt;Foo&gt;()</code> resolves to <code>Foo</code> rather than <code>unknown</code>.</p><p><strong><code>login</code> returned only <code>message</code> when <code>requestBaseUrl</code> was set (fix).</strong><code>login</code> is the one endpoint that resolves to the whole body, so a caller can read <code>full_name</code> and <code>home_page</code>. The check compared the whole URL against <code>/api/method/login</code>, and <code>requestBaseUrl</code> makes that URL absolute, so it stopped matching and <code>login</code> quietly resolved to <code>data.message</code>. It now matches on the path.</p><h3 id="frappeui-plugin-—-one-option-left-breaking" tabindex="-1"><code>FrappeUI</code> plugin — one option left (breaking) <a class="header-anchor" href="#frappeui-plugin-—-one-option-left-breaking" aria-label="Permalink to “FrappeUI plugin — one option left (breaking)”">​</a></h3><p><code>app.use(FrappeUI)</code> accepts <code>resources</code> and nothing else, and no longer installs it by default.</p><ul><li><strong><code>socketio</code> removed.</strong> It defaulted to <code>true</code>, so apps that also built their own socket opened two live socket.io connections per page load.</li><li><strong><code>call</code> removed.</strong> It installed a <code>$call</code> global with no consumers.</li><li><strong><code>config</code> removed (silent).</strong> <code>setConfig</code> is the entry point. One app passed it.</li><li><strong><code>resources</code> no longer defaults to <code>true</code>.</strong> The v1 resources Options API mixin — <code>this.$resources</code>, <code>$getResource</code>, <code>$getDoc</code>, <code>$getListResource</code>, <code>$refetchResource</code> — installs only on <code>app.use(FrappeUI, { resources: true })</code>. Composition API resources are unaffected. <code>resourcesPlugin</code> stays exported for direct installation.</li></ul><p>Because a removed <em>option</em> is ignored rather than rejected, the plugin logs a dev-mode warning naming any option it does not accept and what to use instead.</p><p><strong>Removed features fail loudly, in production too.</strong> A dropped option that evaporates is an annoyance; a dropped feature that evaporates is a mystery crash somewhere else. So:</p><ul><li>A component declaring a <code>resources</code> option without <code>app.use(FrappeUI, { resources: true })</code> throws on creation, naming itself and the fix.</li><li>Reading <code>this.$resources</code> with the option off throws the same advice. Both guards exist because Vue routes what a lifecycle hook throws through its own error handling, which only logs in production — a read throws straight into app code in every build.</li><li>Reading <code>this.$socket</code> or <code>this.$call</code>, the two globals the plugin stopped installing, throws a message naming the replacement instead of returning <code>undefined</code>. Assigning your own — <code>app.config.globalProperties.$socket = io(…)</code> — replaces the guard, before or after <code>app.use(FrappeUI)</code>.</li></ul><p><code>realtime: true</code> on a v1 resource still degrades quietly to a non-realtime resource when no socket is set. That has always been its behaviour and this does not change it.</p><h3 id="data-fetching-v2-—-one-request-per-submit" tabindex="-1">Data fetching (v2) — one request per submit <a class="header-anchor" href="#data-fetching-v2-—-one-request-per-submit" aria-label="Permalink to “Data fetching (v2) — one request per submit”">​</a></h3><p><code>useDoctype</code>&#39;s <code>insert</code>, <code>delete</code>, <code>setValue</code>, <code>runDocMethod</code> and <code>runMethod</code>, and <code>useList</code>&#39;s <code>insert</code>, <code>setValue</code> and <code>delete</code>, each held a single shared request. Two submits at once aborted one another, and every submit resolved from the same <code>data</code>, so a caller could receive another caller&#39;s answer or <code>null</code>. Each submit now sends its own request and resolves with its own response.</p><ul><li><strong>Breaking:</strong> these eight members no longer carry the <code>useCall</code> surface. Removed: <code>params</code>, <code>promise</code>, <code>url</code>, <code>reset</code>, <code>abort</code>, <code>execute</code>, <code>fetch</code>, <code>reload</code>, <code>isFetching</code>, <code>isFinished</code>, <code>canAbort</code>, <code>aborted</code>. Each of them described one shared request, which no longer exists.</li><li>What is left, on all eight: <code>submit()</code>, <code>data</code>, <code>error</code>, <code>loading</code> and <code>isLoading()</code>. <code>loading</code> is true while any submit is in flight.</li><li>New: <code>delete.isLoading(name)</code> and <code>setValue.isLoading(name)</code> on both <code>useDoctype</code> and <code>useList</code>. This replaces the <code>delete.loading &amp;&amp; delete.params.name === row.name</code> idiom, which showed the same spinner on every row once two deletes overlapped.</li><li>New: <code>insert.isLoading()</code> on both, taking no argument. A new document has no name to key on, so it answers for the whole method — the same value as <code>insert.loading</code>. It exists so all eight methods read the same way.</li><li><code>runDocMethod.isLoading(name, method)</code> and <code>runMethod.isLoading(method)</code> keep their signatures and now answer correctly with several submits in flight. They previously compared the shared URL, so only the newest submit read as loading.</li><li><code>data</code> and <code>error</code> belong to the submit that started last, not the one that answered last. A slow submit that comes back after a newer one is dropped: it writes no <code>data</code>, writes no <code>error</code> and clears nothing. It still answers its own caller with its own outcome — resolving with its response, or rejecting with its error.</li><li>The winning submit writes <code>data</code> and <code>error</code> together. Success sets <code>data</code> and clears <code>error</code>. Failure sets <code>error</code> and leaves <code>data</code> alone.</li><li><strong><code>data</code> is no longer reset on failure.</strong> The old shared <code>useCall</code> set <code>data</code> back to <code>null</code> whenever a response came back not-ok. It now keeps the last successful response. Read <code>error</code>, not <code>data</code>, to tell a failed submit from a successful one.</li><li><code>error</code> is no longer cleared when a submit starts. Clearing it there erased the error of a sibling submit that was still in flight. An error stands until the newest submit settles.</li><li><strong><code>submit()</code> now rejects on any failure.</strong> It resolves with the response or rejects with the error — one channel, not two. A failed <code>validate</code> already rejected; a failed request used to resolve with <code>null</code>. Both reject now, and a server that answers with <code>null</code> resolves with <code>null</code>.</li><li><code>useList</code>&#39;s <code>insert</code> and <code>delete</code> now send to <code>baseUrl</code>, which they silently dropped. <code>setValue</code> already used it, so all three write methods now agree. <code>useDoctype</code> was never affected — every one of its methods already passed <code>baseUrl</code>.</li></ul><h3 id="data-fetching-v2-—-usefrappefetch-off-the-root-export-breaking" tabindex="-1">Data fetching (v2) — <code>useFrappeFetch</code> off the root export (breaking) <a class="header-anchor" href="#data-fetching-v2-—-usefrappefetch-off-the-root-export-breaking" aria-label="Permalink to “Data fetching (v2) — useFrappeFetch off the root export (breaking)”">​</a></h3><p><strong><code>useFrappeFetch</code> removed.</strong> It is the raw <code>createFetch</code> instance <code>useCall</code>, <code>useDoc</code> and <code>useList</code> are built on — headers, response parsing and error shaping, and nothing above that: no URL building, no params, no caching, no typed return. No app imports it. It is a build failure at the import; use <code>useCall</code> for a whitelisted method, <code>useDoc</code> for one document, <code>useList</code> for a query.</p><p><strong><code>FrappeResponseError</code> is now exported.</strong> The composables raise it on a Frappe error response and put it on <code>.error</code>, and <code>submit()</code> rejects with it, but nothing exported the class, so a consumer could not narrow the error. Same gap <code>FrappeRequestError</code> closed for <code>frappeRequest</code>.</p><h3 id="data-fetching-v2-—-docs-and-the-sidebar-splits-from-resources" tabindex="-1">Data fetching (v2) — docs, and the sidebar splits from Resources <a class="header-anchor" href="#data-fetching-v2-—-docs-and-the-sidebar-splits-from-resources" aria-label="Permalink to “Data fetching (v2) — docs, and the sidebar splits from Resources”">​</a></h3><p><code>useCall</code>, <code>useDoc</code>, <code>useList</code>, <code>useDoctype</code> and <code>useNewDoc</code> each get a docs page for the first time, under a new <strong>Data Fetching</strong> sidebar section — <code>useCall</code> for a whitelisted method, <code>useDoc</code> for one document, <code>useList</code> for a query, <code>useDoctype</code> for write-only access to a DocType, <code>useNewDoc</code> for a draft-and-insert form.</p><p>The old <strong>Data Fetching</strong> section is renamed <strong>Resources</strong> and keeps its three pages (Resource, List Resource, Document Resource) unchanged. Both sections link to each other: Resources stays fully supported through <code>1.x</code>; the new composables are the recommended layer for new code.</p><h3 id="data-fetching-v2-—-usenewdoc-lost-reactivity-after-submit-fix" tabindex="-1">Data fetching (v2) — <code>useNewDoc</code> lost reactivity after submit (fix) <a class="header-anchor" href="#data-fetching-v2-—-usenewdoc-lost-reactivity-after-submit-fix" aria-label="Permalink to “Data fetching (v2) — useNewDoc lost reactivity after submit (fix)”">​</a></h3><p><code>useNewDoc</code> built its return value with <code>reactive({ ...out, submit, doc })</code>. Spreading a <code>reactive()</code> proxy reads every ref and computed once and freezes the result, so <code>data</code>, <code>error</code> and <code>loading</code> stopped updating the moment the object was built — a template bound to <code>newDoc.loading</code> never saw it flip. The return value is now built by mutating the underlying object in place, so its properties stay live.</p><h3 id="data-fetching-v2-—-initialdata-did-nothing-on-usecall-and-uselist-fix" tabindex="-1">Data fetching (v2) — <code>initialData</code> did nothing on <code>useCall</code> and <code>useList</code> (fix) <a class="header-anchor" href="#data-fetching-v2-—-initialdata-did-nothing-on-usecall-and-uselist-fix" aria-label="Permalink to “Data fetching (v2) — initialData did nothing on useCall and useList (fix)”">​</a></h3><p>Both documented an <code>initialData</code> option to show a placeholder before the first response. Neither worked. <code>useCall</code> passed it straight to the underlying fetch, which expects the wrapped <code>{ data: ... }</code> shape the API actually returns — the unwrapped value was invisible, so <code>call.data</code> stayed <code>null</code> until the first response. <code>useList</code>&#39;s <code>data</code> is read from a separate list built in <code>afterFetch</code>, which <code>initialData</code> never touched, so <code>list.data</code> stayed <code>null</code> the same way. Both now show the seeded value immediately, as documented.</p><h3 id="root-composables-and-directives-—-renamed-and-shrunk" tabindex="-1">Root composables and directives — renamed and shrunk <a class="header-anchor" href="#root-composables-and-directives-—-renamed-and-shrunk" aria-label="Permalink to “Root composables and directives — renamed and shrunk”">​</a></h3><p>Every change below is a <strong>loud break</strong>: the import line fails, so the build, the type-check or the dev server says so. No silent behavior changes, and nothing here needs a migration-guide before/after.</p><p><strong><code>useTheme</code> is now <code>useColorScheme</code>.</strong> <code>theme</code> means color tone everywhere else in the library (<code>theme=&quot;blue&quot;</code> on a Button, ~300 sites), so the light/dark composable stops competing for the word.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// before</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useTheme</span><span class="s_1jjt6x">,</span><span class="s_50ecpt"> type</span><span class="s_4q1z3w"> Theme</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_1jjt6x"> {</span><span class="s_295sjd"> currentTheme</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> setTheme</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> toggleTheme</span><span class="s_1jjt6x"> }</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useTheme</span><span class="s_13ahmt">()</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// after</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useColorScheme</span><span class="s_1jjt6x">,</span><span class="s_50ecpt"> type</span><span class="s_4q1z3w"> ColorScheme</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_1jjt6x"> {</span><span class="s_295sjd"> colorScheme</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> setColorScheme</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> toggleColorScheme</span><span class="s_1jjt6x"> }</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useColorScheme</span><span class="s_13ahmt">()</span></span></code></pre></div><ul><li><code>colorScheme</code> is <strong>read-only</strong>. Assigning to the old <code>currentTheme</code> ref moved the ref without setting <code>data-theme</code> or <code>localStorage</code>, so the app silently desynced. Go through <code>setColorScheme</code>.</li><li><code>initializeTheme</code> and <code>getSystemTheme</code> are gone. <code>useColorScheme()</code> already restores the saved preference and follows the OS on its first call.</li><li><strong>The <code>data-theme</code> attribute and the <code>theme</code> <code>localStorage</code> key are unchanged.</strong> App CSS targeting <code>[data-theme=&#39;dark&#39;]</code> and users&#39; saved preferences keep working.</li></ul><p><strong>Nine scroll members become two.</strong></p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// before</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">activeScrollContainer</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> useScrollContainer</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> scrollToTop</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_1jjt6x"> {</span><span class="s_295sjd"> isScrolled</span><span class="s_1jjt6x"> }</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useScrollContainer</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> threshold</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> 12</span><span class="s_13ahmt"> })</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// after</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">shellScrollContainer</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> useShellScrolled</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> scrolled</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useShellScrolled</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> threshold</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> 12</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_22m8k2">shellScrollContainer</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">?.</span><span class="s_indoxt">scrollTo</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> top</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> 0</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> behavior</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">smooth</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Removed</th><th>Use instead</th></tr></thead><tbody><tr><td><code>activeScrollContainer</code></td><td><code>shellScrollContainer</code></td></tr><tr><td><code>useScrollContainer().isScrolled</code></td><td><code>useShellScrolled()</code></td></tr><tr><td><code>useScrollContainer().el</code></td><td><code>shellScrollContainer</code></td></tr><tr><td><code>getScrollContainer()</code></td><td><code>shellScrollContainer.value</code> (works outside <code>setup()</code> too)</td></tr><tr><td><code>scrollTo(o)</code></td><td><code>shellScrollContainer.value?.scrollTo(o)</code></td></tr><tr><td><code>scrollToTop()</code></td><td><code>shellScrollContainer.value?.scrollTo({ top: 0, behavior: &#39;smooth&#39; })</code></td></tr><tr><td><code>registerScrollContainer</code> / <code>unregisterScrollContainer</code></td><td>internal to <code>DesktopShell</code> / <code>MobileShell</code></td></tr><tr><td><code>UseScrollContainer</code>, <code>UseScrollContainerOptions</code></td><td>no replacement needed</td></tr></tbody></table><p>The <code>shell</code> prefix is deliberate: both resolve only while a <code>DesktopShell</code> or <code>MobileShell</code> is mounted. <code>useShellScrolled</code> now warns once in development when no shell is registered, instead of silently reporting <code>false</code> forever.</p><p><strong>Directives are <code>vFocus</code> and <code>vOnOutsideClick</code>.</strong> <code>&lt;script setup&gt;</code> auto-registers a directive only when the binding is named <code>vFoo</code>, so the old names forced a manual alias at every call site.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_22m8k2">onOutsideClickDirective</span><span class="s_2ekfrt"> as</span><span class="s_4q1z3w"> vOnOutsideClick</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- after --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">vOnOutsideClick</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>visibilityDirective</code> is removed with no replacement (0 call sites). Use an <code>IntersectionObserver</code> directly, or <code>@vueuse/core</code>&#39;s <code>useIntersectionObserver</code>.</p><p><strong><code>useScreenSize</code>, <code>useIsMobile</code> and <code>ScreenSize</code> are no longer exported.</strong> They were a thin wrapper over a <code>resize</code> listener that the library never used itself. Copy the ~20 lines into your app, or use <code>@vueuse/core</code>&#39;s <code>useWindowSize</code> / <code>useMediaQuery</code>.</p><h3 id="code-editor-subpath-—-folded-into-experimental-breaking" tabindex="-1"><code>code-editor</code> subpath — folded into <code>experimental</code> (breaking) <a class="header-anchor" href="#code-editor-subpath-—-folded-into-experimental-breaking" aria-label="Permalink to “code-editor subpath — folded into experimental (breaking)”">​</a></h3><ul><li><p><strong>Breaking:</strong> <code>frappe-ui/code-editor</code> is removed. <code>CodeEditor</code>, <code>CodePreview</code>, and <code>loadLanguage</code> move to <code>frappe-ui/experimental</code> (ADR-0010). One downstream file imported the old subpath; the fix is a one-line import change.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// before</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">CodeEditor</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> CodePreview</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/code-editor</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// after</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">CodeEditor</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> CodePreview</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/experimental</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div></li></ul><h3 id="experimental-barrel-—-tidy-and-frappeuierror" tabindex="-1"><code>experimental</code> barrel — tidy and <code>FrappeUIError</code> <a class="header-anchor" href="#experimental-barrel-—-tidy-and-frappeuierror" aria-label="Permalink to “experimental barrel — tidy and FrappeUIError”">​</a></h3><ul><li><strong>Breaking:</strong> <code>LabelingWrapper</code> is dropped from <code>frappe-ui/experimental</code>. It stays exported from its own barrel (<code>src/components/InputLabeling</code>) — <code>Combobox</code>, <code>Select</code>, <code>MultiSelect</code>, and <code>MultiEmailInput</code> import it from there internally — only the <code>experimental</code> re-export had zero external importers, so only that goes. The only member cut in the barrel tidy.</li><li><code>FrappeUIError</code> is now exported from <code>frappe-ui/experimental</code> as a type. A consumer previously hand-declared a structural copy of it because it wasn&#39;t re-exported — that copy can now be dropped in favor of the real type.</li></ul><h3 id="tsconfig-base-json-—-cleaned-up-breaking-for-extenders" tabindex="-1"><code>tsconfig.base.json</code> — cleaned up (breaking for extenders) <a class="header-anchor" href="#tsconfig-base-json-—-cleaned-up-breaking-for-extenders" aria-label="Permalink to “tsconfig.base.json — cleaned up (breaking for extenders)”">​</a></h3><ul><li><strong>Breaking:</strong> <code>tsconfig.base.json</code> no longer sets <code>types</code> (<code>vitest/globals</code>, <code>unplugin-icons/types/vue</code>, <code>node</code>). If your app extends this file and relies on any of these globals, add <code>types</code> to your own <code>tsconfig.json</code>. Without it, <code>tsc</code> fails with a missing-global error (e.g. <code>Cannot find name &#39;vi&#39;</code>) the first time a global that used to come from <code>vitest/globals</code> or <code>unplugin-icons/types/vue</code> is referenced. <code>noEmit</code> stays — it&#39;s needed to keep <code>allowImportingTsExtensions</code> legal — but the <code>declaration</code> / <code>emitDeclarationOnly</code> pair (contradictory alongside <code>noEmit</code>, and unused by frappe-ui&#39;s own build) is gone.</li></ul><h3 id="hljs-theme-css-export-removed" tabindex="-1"><code>./hljs-theme.css</code> export removed <a class="header-anchor" href="#hljs-theme-css-export-removed" aria-label="Permalink to “./hljs-theme.css export removed”">​</a></h3><ul><li><strong>Breaking:</strong> <code>frappe-ui/hljs-theme.css</code> is no longer exported. It had zero importers. The underlying file (<code>experimental/TextEditor/hljs-github.css</code>) ships until the deprecated <code>TextEditor</code> is removed.</li></ul><h3 id="pagemetaplugin-—-removed" tabindex="-1">pageMetaPlugin — removed <a class="header-anchor" href="#pagemetaplugin-—-removed" aria-label="Permalink to “pageMetaPlugin — removed”">​</a></h3><ul><li><strong>Silent break:</strong> <code>pageMetaPlugin</code> and the global mixin it installed are gone. A leftover <code>pageMeta()</code> component option still compiles but is never read, so <code>document.title</code> and the favicon quietly stop updating. See the <a href="/docs/migration#pagemetaplugin-removed">migration guide</a>.</li><li><code>usePageMeta</code> is unchanged and now exports its <code>PageMeta</code> type.</li></ul><h3 id="gridlayout-—-removed-breaking" tabindex="-1">GridLayout — removed (breaking) <a class="header-anchor" href="#gridlayout-—-removed-breaking" aria-label="Permalink to “GridLayout — removed (breaking)”">​</a></h3><ul><li><strong>Breaking:</strong> <code>GridLayout</code> is no longer exported. It was a thin passthrough to <code>grid-layout-plus</code> with no docs page and no tests. The import fails, so the build names every call site. Depend on <code>grid-layout-plus</code> directly.</li><li><code>grid-layout-plus</code> is dropped from <code>dependencies</code> — it had no other importer left in <code>src/</code>.</li><li>Two bugs in the deleted component, so consumers wiring up <code>grid-layout-plus</code> themselves should expect different behavior: <ul><li><code>cols</code> and <code>rowHeight</code> were read once at setup inside a <code>reactive()</code> options object, not <code>computed</code>, so changing either prop after mount did nothing.</li><li>the drag placeholder color was a hardcoded <code>#b1b1b1</code>, not a theme token, so it ignored dark mode.</li></ul></li></ul><h3 id="app-shell-family-—-brought-to-bar" tabindex="-1">App shell family — brought to bar <a class="header-anchor" href="#app-shell-family-—-brought-to-bar" aria-label="Permalink to “App shell family — brought to bar”">​</a></h3><p><code>DesktopShell</code>, <code>MobileShell</code>, <code>MobileNav</code>, <code>Rail</code>, <code>PageHeader</code>, <code>ScrollArea</code>, and <code>FrappeUIProvider</code> all keep their current exports and names.</p><ul><li>Every slot across the family now has a documented description, and each component has a docs page, a story, and cypress tests (several had none).</li><li><strong>Breaking, silent:</strong> <code>PageHeaderMobile</code>&#39;s <code>#left</code>/<code>#right</code> slots and <code>PageHeaderMobileTitle</code>&#39;s <code>#icon</code> slot are renamed to the shared <code>#prefix</code>/<code>#suffix</code> vocabulary (PHILOSOPHY.md P6 forbids type-specific slots like <code>#icon</code> outside <code>Button</code>, and <code>#left</code>/<code>#right</code> were never in the vocabulary). Vue drops content passed to an unknown slot name with no error, so the old names don&#39;t warn — they just stop rendering. See the <a href="/docs/migration#pageheadermobile-family-slot-names">migration guide</a>.</li><li><code>ScrollArea</code> gets a <code>types.ts</code> (<code>ScrollAreaProps</code>, <code>ScrollBarProps</code>, <code>ScrollAreaExposed</code>) and <code>data-slot=&quot;scroll-area&quot;</code> / <code>&quot;scroll-area-viewport&quot;</code> / <code>&quot;scroll-area-scrollbar&quot;</code> / <code>&quot;scroll-area-thumb&quot;</code> styling hooks — it had none. <code>viewportElement</code> on the template ref is now typed via <code>ScrollAreaExposed</code>. (<code>SettingsDialog</code>&#39;s <code>SettingsBody</code> exposes the same shape today but isn&#39;t wired to this type yet — that&#39;s tracked under SettingsDialog&#39;s own sweep.)</li><li><code>FrappeUIProvider</code>&#39;s source directory moved from <code>src/components/Provider</code> to <code>src/components/FrappeUIProvider</code> to match its file name. Purely internal — <code>import { FrappeUIProvider } from &#39;frappe-ui&#39;</code> is unaffected.</li><li><strong>Breaking:</strong> <code>FrappeUIProviderProps</code> is no longer exported. The component has no props, so the type was empty and never wired to <code>defineProps</code> — freezing it now would lock in nothing. Zero known consumers. The mismatched directory name had made the whole component invisible to the docs generator, so it previously had no docs page.</li></ul><h3 id="frappe-and-drive-subpaths-—-removed-breaking" tabindex="-1"><code>frappe</code> and <code>drive</code> subpaths — removed (breaking) <a class="header-anchor" href="#frappe-and-drive-subpaths-—-removed-breaking" aria-label="Permalink to “frappe and drive subpaths — removed (breaking)”">​</a></h3><ul><li><strong>Breaking:</strong> <code>frappe-ui/frappe</code> is removed and the <code>frappe/</code> directory is deleted (rule 6: frappe-ui is a dumb library; decided in #867, moved in frappe/frappe#41671). <code>useTelemetry</code>, <code>telemetryPlugin</code>, <code>useOnboarding</code>, <code>GettingStartedBanner</code>, <code>IntermediateStepModal</code>, <code>HelpModal</code>, <code>showHelpModal</code>, <code>minimize</code>, <code>TrialBanner</code>, <code>SignupBanner</code>, <code>DataImport</code>, <code>Link</code>, <code>Filter</code> and <code>LinkProps</code> now live in <code>@framework/ui</code>. The <code>Link</code> and <code>Filter</code> there are supersets (<code>Link</code>: <code>redirectable</code>/<code>editable</code> props, <code>redirect</code>/<code>edit</code> emits; <code>Filter</code>: <code>useFilters</code>, <code>parseFilters</code>/<code>serializeFilters</code>, operator registry).</li><li><strong>Breaking:</strong> <code>OnboardingSteps</code>, <code>HelpCenter</code> and <code>showHelpCenter</code> are removed with no standalone replacement — zero call sites across all consumer apps (they still power <code>HelpModal</code> inside <code>@framework/ui</code>).</li><li><strong>Breaking:</strong> <code>frappe-ui/drive</code> and <code>frappe-ui/drive/*</code> are removed with no replacement. No app imported them — the drive app owns the live copy of all six components.</li><li>The <code>content</code> export from <code>frappe-ui/tailwind</code> and the docs no longer list a <code>frappe/**</code> glob; apps hand-maintaining <code>node_modules/frappe-ui/frappe/**</code> in <code>tailwind.config.js</code> should drop the line.</li></ul><h2 id="deprecation-log" tabindex="-1">Deprecation log <a class="header-anchor" href="#deprecation-log" aria-label="Permalink to “Deprecation log”">​</a></h2><table tabindex="0"><thead><tr><th>API</th><th>Replacement</th><th>Notes</th></tr></thead><tbody><tr><td><code>Divider.action.handler</code></td><td><code>Divider.action.onClick</code></td><td><strong>Removed</strong> — silent; key dropped, click does nothing</td></tr><tr><td><code>Password.value</code> prop</td><td><code>v-model</code> / <code>modelValue</code></td><td><strong>Removed in 1.0.0</strong> (ADR-0008)</td></tr><tr><td><code>Rating.rating_from</code> prop</td><td><code>max</code></td><td><strong>Removed</strong> — silent; prop ignored</td></tr><tr><td><code>Rating.readonly</code> prop</td><td><code>disabled</code></td><td><strong>Removed</strong> — silent; prop ignored</td></tr><tr><td><code>Switch.change</code> emit</td><td><code>update:modelValue</code> / <code>v-model</code></td><td><strong>Removed</strong> — silent; listener never fires</td></tr><tr><td><code>Switch.labelClasses</code> prop</td><td><code>data-*</code> styling hooks</td><td><strong>Removed</strong> — silent; prop ignored</td></tr><tr><td><code>Checkbox.padding</code> prop</td><td><code>padded</code> / <code>data-*</code> styling hooks</td><td><strong>Removed</strong> — silent; prop ignored</td></tr><tr><td><code>Dropdown</code> <code>{ group, items }</code></td><td><code>{ group, options }</code></td><td><strong>Removed</strong> — silent; renders empty, dev-only warning</td></tr><tr><td><code>Dropdown.placement</code> prop</td><td><code>align</code></td><td><strong>Removed</strong> — silent; falls back to <code>align=&quot;start&quot;</code></td></tr><tr><td><code>Dropdown</code>/<code>ContextMenu</code> <code>component:</code> rows</td><td><code>slots: { item: fn }</code></td><td><strong>Removed</strong> — silent; renders label-only row, dev-only warning</td></tr><tr><td><code>DropdownExposed</code> type</td><td><code>v-model:open</code> / <code>close</code> slot prop</td><td><strong>Removed</strong> — loud; described an expose that never existed</td></tr><tr><td>Select <code>#item-*</code> slot prop <code>option</code></td><td><code>item</code></td><td><strong>Removed</strong> — silent; <code>{ option }</code> destructures to <code>undefined</code></td></tr><tr><td><code>Input.vue</code></td><td><code>TextInput</code></td><td><strong>Removed in 1.0.0</strong> (ADR-0008)</td></tr><tr><td><code>Autocomplete</code></td><td><code>Combobox</code> or <code>MultiSelect</code></td><td><strong>Removed</strong> — import fails</td></tr><tr><td><code>GridLayout</code></td><td>depend on <code>grid-layout-plus</code> directly</td><td><strong>Removed</strong> — loud; import fails</td></tr><tr><td><code>FormControl type=&#39;autocomplete&#39;</code></td><td><code>type=&quot;combobox&quot;</code>, or <code>Combobox</code> standalone</td><td><strong>Removed</strong> — silent; dev-only <code>console.error</code></td></tr><tr><td>DatePicker family <code>placement</code></td><td><code>side</code> + <code>align</code> + <code>offset</code></td><td><strong>Removed</strong> — silent; inert extra attribute</td></tr><tr><td>DatePicker family <code>autoClose</code></td><td><code>keepOpen</code> (inverse)</td><td><strong>Removed</strong> — silent; inert extra attribute</td></tr><tr><td>DatePicker family <code>allowCustom</code></td><td><code>typeable: false</code></td><td><strong>Removed</strong> — silent; inert extra attribute</td></tr><tr><td>DatePicker family <code>readonly</code></td><td><code>typeable: false</code></td><td><strong>Removed</strong> — silent; inert extra attribute</td></tr><tr><td>DatePicker family <code>inputClass</code></td><td><code>class</code> on the component element</td><td><strong>Removed</strong> — silent; inert extra attribute</td></tr><tr><td>DatePicker family <code>value</code> prop</td><td><code>v-model</code> / <code>modelValue</code></td><td><strong>Removed</strong> — silent; inert extra attribute</td></tr><tr><td>DatePicker family <code>#target</code> slot</td><td><code>#trigger</code></td><td><strong>Removed</strong> — silent; slot content stops rendering</td></tr><tr><td><code>TimePicker.scrollMode</code></td><td>none (always centered)</td><td><strong>Removed</strong> — silent; inert extra attribute</td></tr><tr><td><code>DateTimePicker.minDateTime</code></td><td><code>min</code></td><td><strong>Removed</strong> — silent; constraint no longer enforced</td></tr><tr><td><code>DateTimePicker.maxDateTime</code></td><td><code>max</code></td><td><strong>Removed</strong> — silent; constraint no longer enforced</td></tr><tr><td><code>TimePicker.minTime</code></td><td><code>min</code></td><td><strong>Removed</strong> — silent; constraint no longer enforced</td></tr><tr><td><code>TimePicker.maxTime</code></td><td><code>max</code></td><td><strong>Removed</strong> — silent; constraint no longer enforced</td></tr><tr><td><code>TimePicker.selectAll()</code> / <code>.blurInput()</code></td><td>none — dead, no callers</td><td><strong>Removed</strong> — loud; template-ref member gone</td></tr><tr><td><code>useDatePicker</code> composable</td><td>use picker components directly</td><td><strong>Removed</strong> — loud; import fails</td></tr><tr><td><code>getDate</code> / <code>getDatesAfter</code> / etc.</td><td>use picker components directly</td><td><strong>Removed</strong> — loud; import fails</td></tr><tr><td><code>MonthPicker</code></td><td><code>Select</code></td><td><strong>Removed</strong> — loud; import fails</td></tr><tr><td><code>FeatherIcon</code></td><td><code>lucide-*</code> strings (or a <code>Component</code>)</td><td><strong>Removed</strong> — import fails; feather-name props render nothing, dev-warns once</td></tr><tr><td><code>Card</code></td><td>layout markup</td><td><strong>Removed in 1.0.0</strong> (ADR-0008), import fails</td></tr><tr><td><code>ListItem</code></td><td>layout markup</td><td><strong>Removed in 1.0.0</strong> (ADR-0008), import fails</td></tr><tr><td><code>Toast</code> (SFC)</td><td>imperative <code>toast(...)</code> API</td><td><strong>Removed in 1.0.0</strong> (ADR-0008), import fails</td></tr><tr><td>Dialog legacy <code>options</code> blob</td><td>flat top-level props</td><td><strong>Removed</strong> — silent; inert attr</td></tr><tr><td>Dialog <code>disableOutsideClickToClose</code></td><td><code>dismissible</code> (inverted)</td><td><strong>Removed</strong> — silent; inert attr</td></tr><tr><td>Dialog <code>#body*</code> slots</td><td><code>#default</code> / <code>#title</code> / <code>#actions</code></td><td><strong>Removed</strong> — silent; renders nothing</td></tr><tr><td>Dialog <code>icon.appearance</code></td><td><code>icon.theme</code></td><td><strong>Removed</strong> — silent; icon loses tone</td></tr><tr><td>Dialog action <code>onClick</code> callable context</td><td><code>{ close }</code> object</td><td><strong>Removed</strong> — throws on call</td></tr><tr><td>Dialog template-ref <code>close()</code></td><td><code>v-model:open</code> / <code>close</code> slot prop</td><td><strong>Removed</strong> — throws on call</td></tr><tr><td><code>ConfirmDialog</code> component</td><td><code>dialog.confirm()</code> / <code>dialog.danger()</code></td><td><strong>Removed</strong> — import fails</td></tr><tr><td><code>confirmDialog()</code></td><td><code>dialog.confirm()</code></td><td><strong>Removed</strong> — import fails</td></tr><tr><td><code>FileUploader.uploadArgs</code></td><td>flat props (<code>private</code>, <code>folder</code>, <code>doctype</code>, <code>docname</code>, <code>fieldname</code>, <code>uploadEndpoint</code>, <code>optimize</code>)</td><td><strong>Removed</strong> — silent; inert attr</td></tr><tr><td><code>FileUploader</code> template-ref <code>inputRef</code></td><td><code>openFileSelector</code> slot prop</td><td><strong>Removed</strong> — throws on call</td></tr><tr><td><code>FileUploader</code> slot prop <code>error</code></td><td>always <code>string | null</code>, was <code>unknown</code></td><td><strong>Changed</strong> — silent; <code>.message</code> access renders nothing</td></tr><tr><td><code>useFileUpload</code> / <code>FileUploadHandler</code> unset privacy</td><td>explicit <code>private</code> / <code>is_private</code></td><td><strong>Default changed</strong> — silent; now resolves to private</td></tr><tr><td><code>fileToBase64</code>, <code>formatBytes</code>, <code>getMaxFileSize</code>, <code>fileSizeLimitMessage</code></td><td>none (internal only)</td><td><strong>Removed</strong> — import fails</td></tr><tr><td><code>frappe-ui/charts</code> <code>ColorScheme</code> type</td><td>root <code>ResolvedColorScheme</code> (re-exported from <code>frappe-ui/charts</code>)</td><td><strong>Removed</strong> — loud; type import fails</td></tr></tbody></table>`,291)])])}const m=o(s,[["render",r]]);export{u as __pageData,m as default};
